function finiteNumber(value, fallback = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
}

function positiveInteger(value, fallback = 1) {
    const number = Math.floor(finiteNumber(value, fallback));
    return number > 0 ? number : Math.max(1, Math.floor(fallback));
}

function delay(milliseconds) {
    return new Promise(resolve => setTimeout(resolve, Math.max(0, finiteNumber(milliseconds))));
}

// A55.58 terminal generation fence. L and D intentionally share one runtime slot.
// Once this API no longer owns that slot, any delayed continuation from this older
// generation is stale and must not schedule/dispatch further Auction work.
function auctionRuntimeOwnsSingleton() {
    try { return safeProperty(globalThis, RUNTIME_SLOT) === api; }
    catch (_) { return false; }
}

function auctionRuntimeContinuationBlocked() {
    return shutdownRequested || disposed || !auctionRuntimeOwnsSingleton();
}

function runtimeReplacementHandoffSnapshot() {
    const globalHandoff = safeProperty(globalThis, RUNTIME_HANDOFF_SLOT);
    return {
        generation: Math.max(0, Math.floor(finiteNumber(runtimeReplacementHandoff.generation))),
        previousRuntimeSeen: Boolean(runtimeReplacementHandoff.previousRuntimeSeen),
        previousVersion: String(runtimeReplacementHandoff.previousVersion || ''),
        method: String(runtimeReplacementHandoff.method || 'NONE'),
        waitMs: Math.max(0, Math.floor(finiteNumber(runtimeReplacementHandoff.waitMs))),
        safe: Boolean(runtimeReplacementHandoff.safe),
        status: String(safeProperty(globalHandoff, 'status') || runtimeReplacementHandoff.status || ''),
        currentLoader: safeProperty(globalHandoff, 'token') === runtimeReplacementHandoffToken,
    };
}

function errorText(error) {
    if (error instanceof Error) return error.stack || error.message;
    return String(error);
}

function boundedPush(array, value, maximum) {
    array.push(value);
    if (array.length > maximum) array.splice(0, array.length - maximum);
}

function managedListingTrackingRecordProtected(record) {
    if (!record || managedListingRemainingQuantity(record) <= 0) return false;
    if (finiteNumber(record.intentionalSlotReplacementAt) > 0) return true;
    if (Array.isArray(record.serverSalePushFillCredits) && record.serverSalePushFillCredits.length)
        return true;
    const goodsIdText = String(record.stallGoodsId || '');
    if (!goodsIdText) return false;
    const active = safeProperty(state, 'activeManagedStallByGoodsId');
    if (active && typeof active === 'object' && safeProperty(active, goodsIdText)) return true;
    // Persisted/hot-reload records may be initialized before the active-id map is
    // normalized. A record last positively observed live and not yet marked missing
    // remains authoritative enough to protect from FIFO eviction until reconciliation.
    return finiteNumber(record.a13VerifiedOnLiveStallAt) > 0 &&
        finiteNumber(record.a13MissingSince) <= 0;
}

function managedListingTrackingRecordRetained(record, now = Date.now()) {
    if (!record || managedListingRemainingQuantity(record) <= 0) return false;
    if (now <= finiteNumber(record.trackingUntil, now + 1)) return true;
    // A55.93: age expiry is only a cold-history cleanup boundary. A positively
    // live listing, intentional recovery/slot-replacement record, or record still
    // carrying exact server-sale credits remains authoritative past that age until
    // reconciliation proves it removable. Never trade ownership for a hard array cap.
    return managedListingTrackingRecordProtected(record);
}

function managedListingTrackingRecordSaleTimeEligible(record, completedAt) {
    const completed = Math.max(0, finiteNumber(completedAt));
    if (!record || completed <= 0) return false;
    if (completed + 60000 < finiteNumber(record.listedAt)) return false;
    // The nominal trackingUntil is a cold-history retention horizon, not an
    // expiration date for a server listing we still positively own. If that
    // listing survives beyond the horizon, fallback sales history must still be
    // allowed to close it if an exact SPTradeSell push was missed.
    return completed <= finiteNumber(record.trackingUntil, completed + 1) ||
        managedListingTrackingRecordProtected(record);
}

function compactManagedListingTrackingRecords(records, maximum, now = Date.now()) {
    const cap = Math.max(1, positiveInteger(maximum, 192));
    const list = Array.from(records || []).filter(record =>
        managedListingTrackingRecordRetained(record, now)
    );
    if (list.length <= cap) return list;

    const removable = [];
    for (let index = 0; index < list.length; ++index) {
        if (managedListingTrackingRecordProtected(list[index])) continue;
        removable.push({
            index,
            at: finiteNumber(list[index]?.lastSaleFillAt, list[index]?.listedAt),
        });
    }
    removable.sort((left, right) => left.at - right.at || left.index - right.index);
    const need = Math.max(0, list.length - cap);
    const removeCount = Math.min(need, removable.length);
    if (removeCount <= 0) return list;
    const removeIndexes = new Set(removable.slice(0, removeCount).map(entry => entry.index));
    return list.filter((_, index) => !removeIndexes.has(index));
}

function pushManagedListingTracking(record) {
    if (!record) return undefined;
    const cap = Math.max(64, positiveInteger(config.managedListingTrackingMaximumRecords, 192));
    state.managedListings = compactManagedListingTrackingRecords(
        [...Array.from(state.managedListings || []), record], cap, Date.now()
    );
    return record;
}

function ledger(event, details) {
    boundedPush(state.ledger, { at: Date.now(), event, ...(details || {}) }, 250);
}

function userToast(message) {
    if (config.dungeonBackgroundSuppressToasts && (DUNGEON_COEXIST_PROFILE || auctionDungeonImmediateUiGuard())) {
        ++state.stats.dungeonBackgroundToastsSuppressed;
        return false;
    }
    if (!worldContext || !Promot || typeof Promot.showToast !== 'function') return false;
    try {
        Promot.showToast(worldContext, String(message));
        return true;
    } catch (_) {
        return false;
    }
}

async function requestPutOnGoodsWithDungeonNativeToastShield(
    tradeCtrl,
    item,
    price,
    count,
) {
    const operation = () => tradeCtrl.requestPutOnGoods(item, price, count);
    if (!DUNGEON_COEXIST_PROFILE ||
        !config.dungeonBackgroundSuppressNativeListingToasts ||
        !Promot ||
        typeof Promot.showToast !== 'function') {
        return operation();
    }

    const expectedItemName = String(itemName(finiteNumber(item?.cfgId)) || '').trim();
    const expectedCount = Math.max(1, Math.floor(finiteNumber(count, 1)));
    if (!expectedItemName) return operation();

    const originalShowToast = Promot.showToast;
    const itemNeedle = expectedItemName.toLowerCase();
    const countNeedle = String(expectedCount);
    const countPattern = new RegExp(`(^|\\D)${countNeedle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(\\D|$)`);
    let installed = false;
    let matched = false;

    const shieldedShowToast = function (context, message, ...args) {
        const text = String(message ?? '');
        const normalized = text.toLowerCase();
        const itemIndex = normalized.indexOf(itemNeedle);
        const countSurface = itemIndex >= 0
            ? `${normalized.slice(0, itemIndex)} ${normalized.slice(itemIndex + itemNeedle.length)}`
            : normalized;
        if (!matched && itemIndex >= 0 && countPattern.test(countSurface)) {
            matched = true;
            state.stats.dungeonBackgroundNativeListingToastsSuppressed =
                finiteNumber(state.stats.dungeonBackgroundNativeListingToastsSuppressed) + 1;
            return undefined;
        }
        return originalShowToast.call(this, context, message, ...args);
    };

    try {
        Promot.showToast = shieldedShowToast;
        installed = Promot.showToast === shieldedShowToast;
    } catch (_) {
        installed = false;
    }

    if (!installed) {
        state.stats.dungeonBackgroundNativeListingToastShieldFailures =
            finiteNumber(state.stats.dungeonBackgroundNativeListingToastShieldFailures) + 1;
        return operation();
    }

    try {
        return await operation();
    } finally {
        if (Promot.showToast === shieldedShowToast) {
            try {
                Promot.showToast = originalShowToast;
            } catch (_) {
                state.stats.dungeonBackgroundNativeListingToastShieldFailures =
                    finiteNumber(state.stats.dungeonBackgroundNativeListingToastShieldFailures) + 1;
            }
        }
    }
}

let lastRoutineToastAt = 0;
function routineToast(message, now = Date.now()) {
    // A23: routine buy/list/revenue popups are cosmetic and can wake the game's
    // UI/input layer while the user is alt-tabbed. Keep logs/HUD authoritative.
    if (config.hudSuppressRoutineTradeToasts) return false;
    const gap = Math.max(500, finiteNumber(config.routineToastMinimumGapMs, 1800));
    if (now - lastRoutineToastAt < gap) return false;
    lastRoutineToastAt = now;
    return userToast(message);
}

function listLength(value) {
    if (!value) return 0;
    if (Number.isFinite(Number(value.length))) return Number(value.length);
    if (typeof value.Num === 'function') return finiteNumber(value.Num());
    return 0;
}

async function withTimeout(promise, label, timeoutMs = config.requestTimeoutMs) {
    let timer;
    try {
        return await Promise.race([
            Promise.resolve(promise),
            new Promise((_, reject) => {
                timer = setTimeout(
                    () => reject(new Error(`${label} timed out after ${timeoutMs}ms`)),
                    timeoutMs,
                );
            }),
        ]);
    } finally {
        if (timer !== undefined) clearTimeout(timer);
    }
}

function cancelledRequest(label) {
    const error = new Error(`${label} cancelled before dispatch`);
    error.sharpMistCancelled = true;
    return error;
}

function requestWasCancelled(error) {
    return Boolean(error?.sharpMistCancelled);
}

function isNetworkDisconnectError(error) {
    const text = String(error?.stack || error?.message || error || '');
    return /NetDisconnectedError|network\s+is\s+disconnected|network\s+disconnected/i.test(text);
}

function isRequestTimeoutError(error) {
    return /timed out after \d+ms/i.test(String(error?.stack || error?.message || error || ''));
}

function isListingProtocolBusyError(error) {
    return /ErrorCode=1090000/i.test(String(error?.stack || error?.message || error || ''));
}

function protocolErrorCode(error) {
    const text = String(error?.stack || error?.message || error || '');
    const match = text.match(/ErrorCode=(\d+)/i);
    return match ? Math.max(0, Math.floor(finiteNumber(match[1]))) : 0;
}

function isListingStallStateConflictError(error) {
    // A55.14 live evidence: ErrorCode 9999998 appeared only during a rapid
    // transition into 15/15 stall occupancy, repeated at the mutation floor, then
    // disappeared as soon as a sale/revenue refresh opened a slot. Treat it as a
    // listing stall-state/capacity race, not as a network/frequency failure.
    return protocolErrorCode(error) === 9999998;
}

function listingServerStateConflictHoldActive(now = Date.now()) {
    return now < finiteNumber(listingServerStateConflictHoldUntil);
}

function isServerFrequencyLimitError(error) {
    // Do not classify ErrorCode 1090000 by itself as a rate limit. omegaberg.com has
    // observed it as listing-protocol busy and already handles it separately.
    const text = String(error?.stack || error?.message || error || '');
    return /request_frequency_limit|frequency\s+limit|too\s+many\s+(?:requests|operations)|rate.?limit|请求.*频|操作.*频/i.test(text);
}

function marketMutationKindForLabel(label) {
    const text = String(label || '');
    if (/^Buy\s+/i.test(text)) return 'BUY';
    if (/^List\s+/i.test(text)) return 'LIST';
    if (/^Collect auction earnings$/i.test(text)) return 'COLLECT';
    if (/^Unsocket warehouse equipment\s+/i.test(text)) return 'UNSOCKET';
    if (/^Repair warehouse equipment\s+/i.test(text)) return 'REPAIR';
    if (
        /^Operator delist\s+/i.test(text) ||
        /^Replace weak auction slot\s+/i.test(text) ||
        /^Evict stale Forging\s+/i.test(text) ||
        /^Warehouse smart delist\s+/i.test(text) ||
        /^Warehouse terminal park\s+/i.test(text)
    ) return 'DELIST';
    return '';
}

function clearStrongBuyMutationRunway(reason = '') {
    const wasActive = strongBuyMutationRunwayUntil > 0;
    strongBuyMutationRunwayUntil = 0;
    strongBuyMutationRunwaySignature = '';
    strongBuyMutationRunwayProfit = 0;
    strongBuyMutationRunwayRoi = 0;
    return wasActive;
}

function strongBuyMutationRunwayActive(now = Date.now()) {
    if (!(strongBuyMutationRunwayUntil > 0)) return false;
    if (now < strongBuyMutationRunwayUntil) return true;
    ++state.stats.strongBuyMutationRunwaysExpired;
    clearStrongBuyMutationRunway('expired');
    return false;
}

function armStrongBuyMutationRunway(opportunity, listing, now = Date.now()) {
    if (!config.bulkWallStrongBuyMutationRunwayEnabled || !state.liveArmed || state.pendingBuy)
        return false;
    const profit = Math.max(0, finiteNumber(opportunity?.totalProfit));
    const roi = Math.max(0, finiteNumber(opportunity?.roi));
    const strong = Boolean(
        profit >= Math.max(1, finiteNumber(config.bulkWallStrongBuyMutationRunwayMinimumProfit, 8)) ||
        roi >= Math.max(0, finiteNumber(config.bulkWallStrongBuyMutationRunwayMinimumRoi, 0.04))
    );
    if (!strong) return false;
    strongBuyMutationRunwayUntil = Math.max(
        strongBuyMutationRunwayUntil,
        now + Math.max(250, finiteNumber(config.bulkWallStrongBuyMutationRunwayMs, 3600)),
    );
    strongBuyMutationRunwaySignature = String(listing?.key || opportunity?.signature || '');
    strongBuyMutationRunwayProfit = profit;
    strongBuyMutationRunwayRoi = roi;
    ++state.stats.strongBuyMutationRunwaysArmed;
    return true;
}

async function waitForStrongBuyMutationRunway(label, requestGeneration, dispatchGuard = undefined) {
    const kind = marketMutationKindForLabel(label);
    if (!kind || kind === 'BUY') return 0;
    let waited = 0;
    while (strongBuyMutationRunwayActive(Date.now())) {
        const now = Date.now();
        const remaining = Math.max(0, strongBuyMutationRunwayUntil - now);
        if (!(remaining > 0)) break;
        const sleepMs = Math.max(1, Math.min(
            remaining,
            Math.max(5, finiteNumber(config.bulkWallStrongBuyMutationRunwayPollMs, 25)),
        ));
        ++state.stats.strongBuyMutationRunwayPeerDeferrals;
        state.stats.strongBuyMutationRunwayPeerWaitMs += sleepMs;
        waited += sleepMs;
        await delay(sleepMs);
        if (shutdownRequested || disposed) throw cancelledRequest(`${label} shutdown`);
        if (requestGeneration !== networkGeneration) throw cancelledRequest(label);
        if (dispatchGuard && !dispatchGuard()) throw cancelledRequest(label);
    }
    return waited;
}


function pruneMarketMutationDispatchTimes(now = Date.now()) {
    const windowMs = Math.max(
        1000,
        finiteNumber(config.marketMutationRateResearchWindowMs, 60 * 1000),
    );
    const cutoff = now - windowMs;
    while (marketMutationDispatchTimes.length && marketMutationDispatchTimes[0] <= cutoff)
        marketMutationDispatchTimes.shift();
}

function recordMarketMutationDispatch(label, now = Date.now()) {
    if (!config.marketMutationRateResearchEnabled) return;
    const kind = marketMutationKindForLabel(label);
    if (!kind) return;
    pruneMarketMutationDispatchTimes(now);
    if (lastMarketMutationDispatchAt > 0) {
        marketMutationLastGapMs = Math.max(0, now - lastMarketMutationDispatchAt);
        marketMutationMinimumGapObservedMs = Math.min(
            marketMutationMinimumGapObservedMs,
            marketMutationLastGapMs,
        );
        if (
            marketMutationLastGapMs <
            Math.max(0, finiteNumber(config.marketMutationRateHypothesisMinimumGapMs, 3000))
        ) ++state.stats.marketMutationUnderHypothesisGapDispatches;
    }
    lastMarketMutationDispatchAt = now;
    marketMutationDispatchTimes.push(now);
    ++state.stats.marketMutationDispatches;
    if (kind === 'BUY' && strongBuyMutationRunwayUntil > 0) {
        ++state.stats.strongBuyMutationRunwaysFulfilled;
        clearStrongBuyMutationRunway('buy dispatched');
    }
    marketMutationPeakRollingWindow = Math.max(
        marketMutationPeakRollingWindow,
        marketMutationDispatchTimes.length,
    );
    if (
        marketMutationDispatchTimes.length >
        Math.max(1, positiveInteger(config.marketMutationRateHypothesisMaximumPerWindow, 12))
    ) ++state.stats.marketMutationOverHypothesisWindowDispatches;
}

function marketMutationRequiredGapMs(now = Date.now()) {
    let gapMs = 0;
    if (config.marketMutationHardMinimumGapEnabled)
        gapMs = Math.max(
            gapMs,
            Math.max(0, finiteNumber(config.marketMutationHardMinimumGapMs, 3100)),
        );

    if (
        config.marketMutationExplicitFrequencyGuardEnabled &&
        now < marketMutationExplicitGuardUntil &&
        marketMutationExplicitGuardGapMs > 0
    ) {
        gapMs = Math.max(gapMs, marketMutationExplicitGuardGapMs);
    } else if (now >= marketMutationExplicitGuardUntil) {
        marketMutationExplicitGuardUntil = 0;
        marketMutationExplicitGuardGapMs = 0;
    }
    return gapMs;
}

function marketMutationRequiredWaitMs(label, now = Date.now()) {
    if (!marketMutationKindForLabel(label) || !(lastMarketMutationDispatchAt > 0)) return 0;
    const gapMs = marketMutationRequiredGapMs(now);
    return gapMs > 0
        ? Math.max(0, lastMarketMutationDispatchAt + gapMs - now)
        : 0;
}

function activateMarketMutationExplicitFrequencyGuard(label, error, now = Date.now()) {
    if (!marketMutationKindForLabel(label)) return false;
    ++state.stats.marketMutationExplicitFrequencySignals;
    if (!config.marketMutationExplicitFrequencyGuardEnabled) return false;
    marketMutationExplicitGuardGapMs = Math.max(
        marketMutationExplicitGuardGapMs,
        Math.max(250, finiteNumber(config.marketMutationExplicitFrequencyGapMs, 3000)),
    );
    marketMutationExplicitGuardUntil = Math.max(
        marketMutationExplicitGuardUntil,
        now + Math.max(
            marketMutationExplicitGuardGapMs,
            finiteNumber(config.marketMutationExplicitFrequencyGuardMs, 60 * 1000),
        ),
    );
    ++state.stats.marketMutationExplicitFrequencyGuards;
    log.warn('OMEGAB EXPLICIT SERVER MUTATION FREQUENCY LIMIT; TEMPORARY WRITE GUARD ARMED', {
        request: label,
        mutationKind: marketMutationKindForLabel(label),
        gapMs: marketMutationExplicitGuardGapMs,
        guardMs: Math.max(0, marketMutationExplicitGuardUntil - now),
        rollingWindowDispatches: marketMutationDispatchTimes.length,
        error: String(error?.message || error).slice(0, 180),
    });
    return true;
}

function pruneMarketReadDispatchTimes(now = Date.now()) {
    const trackingEnabled = Boolean(
        config.marketReadPressureTelemetryEnabled || config.nonSuperReadBudgetEnabled
    );
    if (!trackingEnabled) {
        marketReadDispatchTimes.length = 0;
        return;
    }
    const windowMs = Math.max(
        1000,
        finiteNumber(config.marketReadPressureWindowMs, 60 * 1000),
        finiteNumber(config.nonSuperReadBudgetWindowMs, 60 * 1000),
    );
    const cutoff = now - windowMs;
    while (marketReadDispatchTimes.length && marketReadDispatchTimes[0] <= cutoff)
        marketReadDispatchTimes.shift();
}

function marketReadPressureSnapshot(now = Date.now()) {
    pruneMarketReadDispatchTimes(now);
    if (!config.marketReadPressureTelemetryEnabled) {
        return {
            enabled: false,
            dispatchGapMs: effectiveRequestGapMs(now),
            baseDispatchGapMs: finiteNumber(config.minimumRequestGapMs, 150),
            superAggressiveDispatchGapMs: finiteNumber(config.superAggressiveMinimumRequestGapMs, 180),
        };
    }
    const burstWindowMs = Math.max(
        1000,
        Math.min(
            Math.max(1000, finiteNumber(config.marketReadPressureWindowMs, 60 * 1000)),
            finiteNumber(config.marketReadPressureBurstWindowMs, 5 * 1000),
        ),
    );
    const burstCutoff = now - burstWindowMs;
    let burstCount = 0;
    for (let i = marketReadDispatchTimes.length - 1; i >= 0; --i) {
        if (marketReadDispatchTimes[i] <= burstCutoff) break;
        ++burstCount;
    }
    return {
        enabled: true,
        dispatchGapMs: effectiveRequestGapMs(now),
        baseDispatchGapMs: finiteNumber(config.minimumRequestGapMs, 150),
        superAggressiveDispatchGapMs: finiteNumber(config.superAggressiveMinimumRequestGapMs, 180),
        ungovernedGapMaximumStartsPerMinute: Number((60000 / Math.max(1, effectiveRequestGapMs(now))).toFixed(1)),
        burstWindowMs,
        burstDispatches: burstCount,
        burstPerSecond: Number((burstCount * 1000 / burstWindowMs).toFixed(2)),
        rollingWindowMs: Math.max(
            1000,
            finiteNumber(config.marketReadPressureWindowMs, 60 * 1000),
        ),
        rollingWindowDispatches: marketReadDispatchTimes.length,
        rollingPerSecond: Number((
            marketReadDispatchTimes.length * 1000 /
            Math.max(1000, finiteNumber(config.marketReadPressureWindowMs, 60 * 1000))
        ).toFixed(2)),
        peakBurstDispatches: runtimeMarketReadPressureBurstPeak,
        peakRollingDispatches: runtimeMarketReadPressureWindowPeak,
        lifetimePeakBurstDispatches: finiteNumber(state.stats.marketReadPressureBurstPeak),
        lifetimePeakRollingDispatches: finiteNumber(state.stats.marketReadPressureWindowPeak),
    };
}

function recordMarketReadDispatch(label, now = Date.now()) {
    if (!(config.marketReadPressureTelemetryEnabled || config.nonSuperReadBudgetEnabled)) return;
    if (marketMutationKindForLabel(label)) return;
    pruneMarketReadDispatchTimes(now);
    marketReadDispatchTimes.push(now);
    ++state.stats.marketReadDispatches;

    if (config.marketReadPressureTelemetryEnabled) {
        const burstWindowMs = Math.max(
            1000,
            Math.min(
                Math.max(1000, finiteNumber(config.marketReadPressureWindowMs, 60 * 1000)),
                finiteNumber(config.marketReadPressureBurstWindowMs, 5 * 1000),
            ),
        );
        const burstCutoff = now - burstWindowMs;
        let burstCount = 0;
        for (let i = marketReadDispatchTimes.length - 1; i >= 0; --i) {
            if (marketReadDispatchTimes[i] <= burstCutoff) break;
            ++burstCount;
        }
        runtimeMarketReadPressureBurstPeak = Math.max(
            runtimeMarketReadPressureBurstPeak, burstCount
        );
        runtimeMarketReadPressureWindowPeak = Math.max(
            runtimeMarketReadPressureWindowPeak, marketReadDispatchTimes.length
        );
        state.stats.marketReadPressureBurstPeak = Math.max(
            finiteNumber(state.stats.marketReadPressureBurstPeak),
            runtimeMarketReadPressureBurstPeak,
        );
        state.stats.marketReadPressureWindowPeak = Math.max(
            finiteNumber(state.stats.marketReadPressureWindowPeak),
            runtimeMarketReadPressureWindowPeak,
        );
    }
    if (!superAggressiveModeActive()) {
        const nonSuperSnapshot = nonSuperReadBudgetSnapshot(now);
        runtimeNonSuperReadBudgetBurstPeak = Math.max(
            runtimeNonSuperReadBudgetBurstPeak, finiteNumber(nonSuperSnapshot.burstReads)
        );
        runtimeNonSuperReadBudgetWindowPeak = Math.max(
            runtimeNonSuperReadBudgetWindowPeak, finiteNumber(nonSuperSnapshot.rollingReads)
        );
        state.stats.nonSuperReadBudgetBurstPeak = Math.max(
            finiteNumber(state.stats.nonSuperReadBudgetBurstPeak),
            runtimeNonSuperReadBudgetBurstPeak,
        );
        state.stats.nonSuperReadBudgetWindowPeak = Math.max(
            finiteNumber(state.stats.nonSuperReadBudgetWindowPeak),
            runtimeNonSuperReadBudgetWindowPeak,
        );
    }
}

function effectiveNonSuperReadBudgetMaximumStarts() {
    const normal = Math.max(1, Math.floor(finiteNumber(config.nonSuperReadBudgetMaximumStarts, 285)));
    if (auctionDungeonActive()) {
        let maximum = Math.min(normal, Math.max(1, Math.floor(finiteNumber(config.dungeonBackgroundReadBudgetMaximumStarts, 180))));
        if (combatPeerCoexistenceSnapshot().active)
            maximum = Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonCombatPeerReadBudgetMaximumStarts, 150))));
        const pressure = autoLootDungeonPressureLevel();
        if (pressure >= 2) {
            maximum = Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootBusyReadBudgetMaximumStarts, 120))));
        } else if (pressure === 1) {
            maximum = Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootActiveReadBudgetMaximumStarts, 150))));
        }
        return maximum;
    }
    if (!hoardTurboSearchActive() || superAggressiveModeActive()) return normal;
    return Math.max(1, Math.min(normal, Math.floor(
        finiteNumber(config.hoardTurboNonSuperReadBudgetMaximumStarts, 275)
    )));
}

function effectiveNonSuperReadBudgetBurstMaximumStarts() {
    const normal = Math.max(1, Math.floor(finiteNumber(config.nonSuperReadBudgetBurstMaximumStarts, 30)));
    if (auctionDungeonActive()) {
        let maximum = Math.min(normal, Math.max(1, Math.floor(finiteNumber(config.dungeonBackgroundReadBudgetBurstMaximumStarts, 18))));
        if (combatPeerCoexistenceSnapshot().active)
            maximum = Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonCombatPeerReadBudgetBurstMaximumStarts, 15))));
        const pressure = autoLootDungeonPressureLevel();
        if (pressure >= 2) return Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootBusyReadBudgetBurstMaximumStarts, 12))));
        if (pressure === 1) return Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootActiveReadBudgetBurstMaximumStarts, 15))));
        return maximum;
    }
    if (!hoardTurboSearchActive() || superAggressiveModeActive()) return normal;
    return Math.max(1, Math.min(normal, Math.floor(
        finiteNumber(config.hoardTurboNonSuperReadBudgetBurstMaximumStarts, 28)
    )));
}

function nonSuperReadBudgetSnapshot(now = Date.now()) {
    pruneMarketReadDispatchTimes(now);
    const rollingWindowMs = Math.max(1000, finiteNumber(config.nonSuperReadBudgetWindowMs, 60 * 1000));
    const burstWindowMs = Math.max(
        1000,
        Math.min(rollingWindowMs, finiteNumber(config.nonSuperReadBudgetBurstWindowMs, 5 * 1000)),
    );
    const burstCutoff = now - burstWindowMs;
    let burstCount = 0;
    for (let i = marketReadDispatchTimes.length - 1; i >= 0; --i) {
        if (marketReadDispatchTimes[i] <= burstCutoff) break;
        ++burstCount;
    }
    return {
        enabled: !!config.nonSuperReadBudgetEnabled,
        enforced: !!config.nonSuperReadBudgetEnabled && !superAggressiveModeActive(),
        burstWindowMs,
        burstMaximumReads: effectiveNonSuperReadBudgetBurstMaximumStarts(),
        burstReads: burstCount,
        rollingWindowMs,
        rollingMaximumReads: effectiveNonSuperReadBudgetMaximumStarts(),
        rollingReads: marketReadDispatchTimes.length,
        burstPeak: runtimeNonSuperReadBudgetBurstPeak,
        rollingPeak: runtimeNonSuperReadBudgetWindowPeak,
        lifetimeBurstPeak: finiteNumber(state.stats.nonSuperReadBudgetBurstPeak),
        lifetimeRollingPeak: finiteNumber(state.stats.nonSuperReadBudgetWindowPeak),
    };
}

function nonSuperReadBudgetRequiredWaitMs(label, now = Date.now()) {
    if (!config.nonSuperReadBudgetEnabled || superAggressiveModeActive() || marketMutationKindForLabel(label)) return 0;
    pruneMarketReadDispatchTimes(now);
    const rollingWindowMs = Math.max(1000, finiteNumber(config.nonSuperReadBudgetWindowMs, 60 * 1000));
    const rollingMaximum = effectiveNonSuperReadBudgetMaximumStarts();
    const burstWindowMs = Math.max(1000, Math.min(rollingWindowMs, finiteNumber(config.nonSuperReadBudgetBurstWindowMs, 5 * 1000)));
    const burstMaximum = effectiveNonSuperReadBudgetBurstMaximumStarts();
    let requiredWait = 0;
    if (marketReadDispatchTimes.length >= rollingMaximum) {
        const index = Math.max(0, marketReadDispatchTimes.length - rollingMaximum);
        requiredWait = Math.max(requiredWait, marketReadDispatchTimes[index] + rollingWindowMs - now + 1);
    }
    const burstCutoff = now - burstWindowMs;
    let burstCount = 0;
    let burstOldestIndex = marketReadDispatchTimes.length;
    for (let i = marketReadDispatchTimes.length - 1; i >= 0; --i) {
        if (marketReadDispatchTimes[i] <= burstCutoff) break;
        burstOldestIndex = i;
        ++burstCount;
    }
    if (burstCount >= burstMaximum && burstOldestIndex < marketReadDispatchTimes.length) {
        const index = Math.max(burstOldestIndex, marketReadDispatchTimes.length - burstMaximum);
        requiredWait = Math.max(requiredWait, marketReadDispatchTimes[index] + burstWindowMs - now + 1);
    }
    return Math.max(0, requiredWait);
}

function nonSuperPriorityExactReadLabel(label) {
    return /^Exact-affix average\s+/i.test(String(label || ''));
}

function nonSuperPriorityExactReadFastLaneEligible(label, now = Date.now()) {
    if (!config.nonSuperPriorityExactReadEnabled || superAggressiveModeActive()) return false;
    if (!nonSuperPriorityExactReadLabel(label) || marketMutationKindForLabel(label)) return false;
    if (shutdownRequested || disposed || disconnectedSince || now < backoffUntil) return false;
    const timeoutWindowMs = Math.max(1000, finiteNumber(config.requestTimeoutRecoveryWindowMs, 10000));
    if (lastRequestTimeoutAt > 0 && now - lastRequestTimeoutAt < timeoutWindowMs) return false;
    const maximumActiveBeforeDispatch = Math.max(0, Math.floor(finiteNumber(config.nonSuperPriorityExactReadMaximumActiveBeforeDispatch, 1)));
    return activeNetworkRequests <= maximumActiveBeforeDispatch;
}

function nonSuperPriorityExactReadGapMs() {
    return Math.max(75, Math.min(
        Math.max(75, finiteNumber(config.minimumRequestGapMs, 150)),
        finiteNumber(config.nonSuperPriorityExactReadGapMs, 100),
    ));
}


function aggressiveReadAheadModeActive() {
    const mode = operatorRarityMode();
    return mode === 'AGGRESSIVE' || mode === 'HIGH_ROLLER';
}

function hoardTurboSearchActive() {
    return Boolean(
        config.hoardTurboSearchEnabled &&
        operatorDesiredHoard() &&
        !operatorDesiredReadOnlyAllMarket()
    );
}

function itemRapidWatchEffectiveEnabled() {
    return Boolean(config.itemRapidWatchEnabled || hoardTurboSearchActive());
}

function hoardTurboMaximumTotalReadLanes() {
    if (!hoardTurboSearchActive()) return 1;
    const mode = operatorRarityMode();
    if (mode === 'SUPER_AGGRESSIVE')
        return Math.max(1, Math.min(5, positiveInteger(config.superAggressiveReadAheadMaximumTotalReadLanes, 5)));
    if (mode === 'PASSIVE')
        return Math.max(1, Math.min(3, positiveInteger(config.hoardTurboPassiveMaximumTotalReadLanes, 2)));
    if (mode === 'MIDDLE')
        return Math.max(1, Math.min(3, positiveInteger(config.hoardTurboMiddleMaximumTotalReadLanes, 3)));
    if (mode === 'AGGRESSIVE')
        return Math.max(1, Math.min(3, positiveInteger(config.hoardTurboAggressiveMaximumTotalReadLanes, 3)));
    if (mode === 'AUTO') {
        const regime = String(state.autoRarityRegime || 'MIDDLE').toUpperCase();
        if (regime === 'PASSIVE')
            return Math.max(1, Math.min(3, positiveInteger(config.hoardTurboAutoPassiveMaximumTotalReadLanes, 2)));
        if (regime === 'AGGRESSIVE')
            return Math.max(1, Math.min(3, positiveInteger(config.hoardTurboAutoAggressiveMaximumTotalReadLanes, 3)));
        return Math.max(1, Math.min(3, positiveInteger(config.hoardTurboAutoMiddleMaximumTotalReadLanes, 3)));
    }
    return 2;
}

function categoryReadAheadModeActive() {
    return superAggressiveModeActive() || aggressiveReadAheadModeActive() || hoardTurboSearchActive();
}

function effectiveSuperAggressiveBurstMaximumStarts() {
    const normal = Math.max(1, Math.floor(finiteNumber(config.superAggressiveRequestBudgetBurstMaximumStarts, 24)));
    if (!auctionDungeonActive()) return normal;
    let maximum = Math.min(normal, Math.max(1, Math.floor(finiteNumber(config.dungeonBackgroundSuperBurstMaximumStarts, 18))));
    if (combatPeerCoexistenceSnapshot().active)
        maximum = Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonCombatPeerReadBudgetBurstMaximumStarts, 15))));
    const pressure = autoLootDungeonPressureLevel();
    if (pressure >= 2) return Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootBusyReadBudgetBurstMaximumStarts, 12))));
    if (pressure === 1) return Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootActiveReadBudgetBurstMaximumStarts, 15))));
    return maximum;
}

function superAggressiveEdgePressureCounts() {
    return {
        networkDisconnects: finiteNumber(state.stats.networkDisconnects),
        networkRequestDisconnectErrors: finiteNumber(state.stats.networkRequestDisconnectErrors),
        marketReadDisconnectsObserved: finiteNumber(state.stats.marketReadDisconnectsObserved),
        serverFrequencyLimitSignals: finiteNumber(state.stats.serverFrequencyLimitSignals),
        requestTimeouts: finiteNumber(state.stats.requestTimeouts),
    };
}

function resetSuperAggressiveEdgeCalibration(now = Date.now(), reason = 'mode entry') {
    const base = Math.max(1, Math.floor(finiteNumber(config.superAggressiveRequestBudgetMaximumStarts, 225)));
    superAggressiveEdgeCurrentMaximum = base;
    superAggressiveEdgeLastSafeMaximum = base;
    superAggressiveEdgeStageStartedAt = now;
    superAggressiveEdgeDisabledForSession = false;
    superAggressiveEdgeBaselineLatencyEmaMs = requestLatencySamples > 0 && requestLatencyEmaMs > 0
        ? requestLatencyEmaMs : 0;
    superAggressiveEdgePressureSnapshot = superAggressiveEdgePressureCounts();
    log.info('OMEGAB SUPER EDGE CALIBRATION ARMED', {
        reason: String(reason || 'mode entry'),
        currentMaximumStartsPerMinute: superAggressiveEdgeCurrentMaximum,
        maximumExperimentalStartsPerMinute: Math.max(base, Math.floor(finiteNumber(config.superAggressiveEdgeMaximumStarts, 235))),
        burstMaximumStartsPer5s: effectiveSuperAggressiveBurstMaximumStarts(),
        minimumGapMs: Math.max(0, finiteNumber(config.superAggressiveMinimumRequestGapMs, 180)),
    });
}

function superAggressiveEdgeRollingMaximum(now = Date.now()) {
    const base = Math.max(1, Math.floor(finiteNumber(config.superAggressiveRequestBudgetMaximumStarts, 225)));
    if (auctionDungeonActive(now)) {
        let maximum = Math.min(base, Math.max(1, Math.floor(finiteNumber(config.dungeonBackgroundSuperMaximumStarts, 180))));
        if (combatPeerCoexistenceSnapshot(now).active)
            maximum = Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonCombatPeerReadBudgetMaximumStarts, 150))));
        const pressure = autoLootDungeonPressureLevel();
        if (pressure >= 2) return Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootBusyReadBudgetMaximumStarts, 120))));
        if (pressure === 1) return Math.min(maximum, Math.max(1, Math.floor(finiteNumber(config.dungeonAutoLootActiveReadBudgetMaximumStarts, 150))));
        return maximum;
    }
    if (!config.superAggressiveEdgeCalibrationEnabled || !superAggressiveModeActive()) return base;
    if (!(superAggressiveEdgeCurrentMaximum >= base)) superAggressiveEdgeCurrentMaximum = base;
    const pressure = superAggressiveEdgePressureCounts();
    const previous = superAggressiveEdgePressureSnapshot || {};
    const maximum = Math.max(base, Math.floor(finiteNumber(config.superAggressiveEdgeMaximumStarts, 235)));
    const hardPressureKeys = [
        'networkDisconnects',
        'networkRequestDisconnectErrors',
        'marketReadDisconnectsObserved',
        'serverFrequencyLimitSignals',
    ];
    const hardPressureChanged = hardPressureKeys.some(
        key => finiteNumber(pressure[key]) > finiteNumber(previous[key])
    );
    const timeoutPressureChanged =
        finiteNumber(pressure.requestTimeouts) > finiteNumber(previous.requestTimeouts);
    const experimentalStageActive =
        superAggressiveEdgeCurrentMaximum > Math.max(base, superAggressiveEdgeLastSafeMaximum);

    // A55.11: 235/min is already the proven baseline. A handful of isolated exact
    // book timeouts in a 24-category SUPER sweep are not evidence that the proven
    // baseline itself is unsafe. They still trigger the normal per-request backoff.
    // If a future build raises the ceiling above the proven base, the same timeout
    // signal once again rolls that experimental stage back to lastSafe.
    if (experimentalStageActive && (hardPressureChanged || timeoutPressureChanged)) {
        const before = superAggressiveEdgeCurrentMaximum;
        superAggressiveEdgeCurrentMaximum = Math.max(base, superAggressiveEdgeLastSafeMaximum);
        superAggressiveEdgeDisabledForSession = true;
        superAggressiveEdgeStageStartedAt = now;
        superAggressiveEdgePressureSnapshot = pressure;
        ++state.stats.superAggressiveEdgeRollbacks;
        log.warn('OMEGAB SUPER EDGE HARD PRESSURE; EXPERIMENT ROLLED BACK', {
            beforeStartsPerMinute: before,
            restoredStartsPerMinute: superAggressiveEdgeCurrentMaximum,
            furtherStepUpsDisabledThisRun: true,
            pressure,
        });
        return superAggressiveEdgeCurrentMaximum;
    }
    if (!experimentalStageActive && maximum > base && hardPressureChanged) {
        // Hard network/frequency pressure at the proven baseline should prevent a
        // later experimental step-up this run, but it is not a fake 235->235 rollback.
        superAggressiveEdgeDisabledForSession = true;
        superAggressiveEdgeStageStartedAt = now;
        log.warn('OMEGAB SUPER BASELINE HARD PRESSURE; FUTURE EDGE STEP-UPS DISABLED', {
            provenStartsPerMinute: base,
            pressure,
        });
    }
    superAggressiveEdgePressureSnapshot = pressure;

    if (!(superAggressiveEdgeBaselineLatencyEmaMs > 0) && requestLatencySamples > 0 && requestLatencyEmaMs > 0)
        superAggressiveEdgeBaselineLatencyEmaMs = requestLatencyEmaMs;

    // Only experimental steps (> proven base) are soft-rolled back on RTT deterioration.
    if (superAggressiveEdgeCurrentMaximum > base && requestLatencySamples >= 5 && requestLatencyEmaMs > 0) {
        const absolute = Math.max(250, finiteNumber(config.superAggressiveEdgeSoftRollbackMinimumEmaMs, 360));
        const baseline = superAggressiveEdgeBaselineLatencyEmaMs > 0 ? superAggressiveEdgeBaselineLatencyEmaMs : requestLatencyEmaMs;
        const multiplier = Math.max(1.10, finiteNumber(config.superAggressiveEdgeSoftRollbackBaselineMultiplier, 1.65));
        const softCeiling = Math.max(absolute, baseline * multiplier);
        if (requestLatencyEmaMs > softCeiling) {
            const before = superAggressiveEdgeCurrentMaximum;
            superAggressiveEdgeCurrentMaximum = Math.max(base, superAggressiveEdgeLastSafeMaximum);
            superAggressiveEdgeDisabledForSession = true;
            superAggressiveEdgeStageStartedAt = now;
            ++state.stats.superAggressiveEdgeRollbacks;
            ++state.stats.superAggressiveEdgeSoftRollbacks;
            log.warn('OMEGAB SUPER EDGE RTT PRESSURE; EXPERIMENT ROLLED BACK', {
                beforeStartsPerMinute: before,
                restoredStartsPerMinute: superAggressiveEdgeCurrentMaximum,
                requestLatencyEmaMs: Number(requestLatencyEmaMs.toFixed(1)),
                softCeilingMs: Number(softCeiling.toFixed(1)),
                furtherStepUpsDisabledThisRun: true,
            });
            return superAggressiveEdgeCurrentMaximum;
        }
    }

    if (superAggressiveEdgeDisabledForSession) return superAggressiveEdgeCurrentMaximum;
    if (superAggressiveEdgeCurrentMaximum >= maximum) return superAggressiveEdgeCurrentMaximum;
    const cleanStageMs = Math.max(60 * 1000, finiteNumber(config.superAggressiveEdgeCleanStageMs, 3 * 60 * 1000));
    const minimumSamples = Math.max(5, positiveInteger(config.superAggressiveEdgeMinimumLatencySamples, 60));
    const maximumEmaMs = Math.max(150, finiteNumber(config.superAggressiveEdgeStepMaximumEmaMs, 300));
    if (
        now - superAggressiveEdgeStageStartedAt >= cleanStageMs &&
        requestLatencySamples >= minimumSamples && requestLatencyEmaMs > 0 && requestLatencyEmaMs <= maximumEmaMs
    ) {
        superAggressiveEdgeLastSafeMaximum = superAggressiveEdgeCurrentMaximum;
        const step = Math.max(1, positiveInteger(config.superAggressiveEdgeStepStarts, 5));
        superAggressiveEdgeCurrentMaximum = Math.min(maximum, superAggressiveEdgeCurrentMaximum + step);
        superAggressiveEdgeStageStartedAt = now;
        superAggressiveEdgeBaselineLatencyEmaMs = requestLatencyEmaMs;
        ++state.stats.superAggressiveEdgeStepUps;
        log.success('OMEGAB SUPER EDGE CLEAN STAGE; CEILING RAISED', {
            lastProvenStartsPerMinute: superAggressiveEdgeLastSafeMaximum,
            experimentalStartsPerMinute: superAggressiveEdgeCurrentMaximum,
            requestLatencyEmaMs: Number(requestLatencyEmaMs.toFixed(1)),
            nextMaximumStartsPerMinute: maximum,
            burstCapUnchanged: effectiveSuperAggressiveBurstMaximumStarts(),
        });
    }
    return superAggressiveEdgeCurrentMaximum;
}

function pruneMarketRequestDispatchTimes(now = Date.now()) {
    const windowMs = Math.max(
        1000,
        finiteNumber(config.superAggressiveRequestBudgetWindowMs, 60 * 1000),
    );
    const cutoff = now - windowMs;
    while (marketRequestDispatchTimes.length && marketRequestDispatchTimes[0] <= cutoff)
        marketRequestDispatchTimes.shift();
}

function superAggressiveRequestBudgetSnapshot(now = Date.now()) {
    pruneMarketRequestDispatchTimes(now);
    const rollingWindowMs = Math.max(1000, finiteNumber(config.superAggressiveRequestBudgetWindowMs, 60 * 1000));
    const rollingMaximum = superAggressiveEdgeRollingMaximum(now);
    const burstWindowMs = Math.max(
        1000,
        Math.min(rollingWindowMs, finiteNumber(config.superAggressiveRequestBudgetBurstWindowMs, 5 * 1000)),
    );
    const burstCutoff = now - burstWindowMs;
    let burstCount = 0;
    for (let i = marketRequestDispatchTimes.length - 1; i >= 0; --i) {
        if (marketRequestDispatchTimes[i] <= burstCutoff) break;
        ++burstCount;
    }
    return {
        enabled: !!config.superAggressiveRequestBudgetEnabled,
        enforced: !!config.superAggressiveRequestBudgetEnabled && superAggressiveModeActive(),
        minimumGapMs: Math.max(0, finiteNumber(config.superAggressiveMinimumRequestGapMs, 180)),
        burstWindowMs,
        burstMaximumStarts: effectiveSuperAggressiveBurstMaximumStarts(),
        burstDispatches: burstCount,
        rollingWindowMs,
        rollingMaximumStarts: rollingMaximum,
        effectiveSustainedMaximumStartsPerMinute: rollingMaximum,
        rollingDispatches: marketRequestDispatchTimes.length,
        burstPeak: runtimeSuperAggressiveRequestBudgetBurstPeak,
        rollingPeak: runtimeSuperAggressiveRequestBudgetWindowPeak,
        lifetimeBurstPeak: finiteNumber(state.stats.superAggressiveRequestBudgetBurstPeak),
        lifetimeRollingPeak: finiteNumber(state.stats.superAggressiveRequestBudgetWindowPeak),
    };
}

function superAggressiveRequestBudgetRequiredWaitMs(now = Date.now()) {
    if (!config.superAggressiveRequestBudgetEnabled || !superAggressiveModeActive()) return 0;
    pruneMarketRequestDispatchTimes(now);

    const rollingWindowMs = Math.max(1000, finiteNumber(config.superAggressiveRequestBudgetWindowMs, 60 * 1000));
    const rollingMaximum = superAggressiveEdgeRollingMaximum(now);
    const burstWindowMs = Math.max(
        1000,
        Math.min(rollingWindowMs, finiteNumber(config.superAggressiveRequestBudgetBurstWindowMs, 5 * 1000)),
    );
    const burstMaximum = effectiveSuperAggressiveBurstMaximumStarts();

    let requiredWait = 0;
    if (marketRequestDispatchTimes.length >= rollingMaximum) {
        const index = Math.max(0, marketRequestDispatchTimes.length - rollingMaximum);
        requiredWait = Math.max(requiredWait, marketRequestDispatchTimes[index] + rollingWindowMs - now + 1);
    }

    const burstCutoff = now - burstWindowMs;
    let burstCount = 0;
    let burstOldestIndex = marketRequestDispatchTimes.length;
    for (let i = marketRequestDispatchTimes.length - 1; i >= 0; --i) {
        if (marketRequestDispatchTimes[i] <= burstCutoff) break;
        burstOldestIndex = i;
        ++burstCount;
    }
    if (burstCount >= burstMaximum && burstOldestIndex < marketRequestDispatchTimes.length) {
        const index = Math.max(burstOldestIndex, marketRequestDispatchTimes.length - burstMaximum);
        requiredWait = Math.max(requiredWait, marketRequestDispatchTimes[index] + burstWindowMs - now + 1);
    }
    return Math.max(0, requiredWait);
}

function recordMarketRequestDispatch(now = Date.now()) {
    pruneMarketRequestDispatchTimes(now);
    marketRequestDispatchTimes.push(now);
    const snapshot = superAggressiveRequestBudgetSnapshot(now);
    runtimeSuperAggressiveRequestBudgetBurstPeak = Math.max(
        runtimeSuperAggressiveRequestBudgetBurstPeak, finiteNumber(snapshot.burstDispatches)
    );
    runtimeSuperAggressiveRequestBudgetWindowPeak = Math.max(
        runtimeSuperAggressiveRequestBudgetWindowPeak, finiteNumber(snapshot.rollingDispatches)
    );
    state.stats.superAggressiveRequestBudgetBurstPeak = Math.max(
        finiteNumber(state.stats.superAggressiveRequestBudgetBurstPeak),
        runtimeSuperAggressiveRequestBudgetBurstPeak,
    );
    state.stats.superAggressiveRequestBudgetWindowPeak = Math.max(
        finiteNumber(state.stats.superAggressiveRequestBudgetWindowPeak),
        runtimeSuperAggressiveRequestBudgetWindowPeak,
    );
}

function effectiveRequestGapMs(now = Date.now()) {
    const base = Math.max(0, finiteNumber(config.minimumRequestGapMs, 150));
    let modeFloor = superAggressiveModeActive()
        ? Math.max(base, finiteNumber(config.superAggressiveMinimumRequestGapMs, 180))
        : base;
    if (auctionDungeonActive(now) && DUNGEON_COEXIST_PROFILE) {
        if (combatPeerCoexistenceSnapshot(now).active)
            modeFloor = Math.max(modeFloor, finiteNumber(config.dungeonCombatPeerRequestGapMs, 200));
        const pressure = autoLootDungeonPressureLevel();
        if (pressure >= 2) modeFloor = Math.max(modeFloor, finiteNumber(config.dungeonAutoLootBusyRequestGapMs, 250));
        else if (pressure === 1) modeFloor = Math.max(modeFloor, finiteNumber(config.dungeonAutoLootActiveRequestGapMs, 200));
    }
    const recovery = Math.max(modeFloor, finiteNumber(config.requestTimeoutRecoveryGapMs, 300));
    const windowMs = Math.max(1000, finiteNumber(config.requestTimeoutRecoveryWindowMs, 10000));
    return lastRequestTimeoutAt > 0 && now - lastRequestTimeoutAt < windowMs ? recovery : modeFloor;
}

function observeRequestLatency(milliseconds) {
    const sample = Math.max(0, finiteNumber(milliseconds));
    if (!(sample > 0)) return;
    const maximum = Math.max(1000, finiteNumber(config.requestLatencySampleMaximumMs, 5000));
    if (sample > maximum) {
        ++state.stats.requestLatencyOutliersRejected;
        return;
    }
    const alpha = 0.20;
    requestLatencyEmaMs = requestLatencySamples > 0
        ? requestLatencyEmaMs * (1 - alpha) + sample * alpha
        : sample;
    ++requestLatencySamples;
}

function readTimeoutTailBoostMs(now = Date.now()) {
    const windowMs = Math.max(5000, finiteNumber(config.readTimeoutTailBoostWindowMs, 60 * 1000));
    if (!(lastRequestTimeoutAt > 0) || now - lastRequestTimeoutAt >= windowMs) return 0;
    return Math.max(0, finiteNumber(config.readTimeoutTailBoostMs, 600));
}

function readTimeoutTailBoostRemainingMs(now = Date.now()) {
    const windowMs = Math.max(5000, finiteNumber(config.readTimeoutTailBoostWindowMs, 60 * 1000));
    return lastRequestTimeoutAt > 0
        ? Math.max(0, windowMs - (now - lastRequestTimeoutAt))
        : 0;
}

function adaptiveExactQueryTimeoutMs() {
    const baseMinimum = Math.max(
        2000,
        finiteNumber(config.exactQueryMinimumTimeoutMs, 2500),
    );
    const ceiling = Math.max(baseMinimum, finiteNumber(config.exactQueryTimeoutMs, 6000));
    const minimum = Math.min(ceiling, baseMinimum + readTimeoutTailBoostMs());
    if (requestLatencySamples < 5 || !(requestLatencyEmaMs > 0)) return ceiling;
    // v4.7.6 + A55.31: healthy books retain the fast adaptive floor. A recent
    // timeout temporarily widens only the settle window; dispatch pacing is unchanged.
    return Math.max(minimum, Math.min(
        ceiling,
        Math.round(requestLatencyEmaMs * 4 + 700),
    ));
}

function adaptiveCategoryQueryTimeoutMs() {
    const configuredMinimum = superAggressiveModeActive()
        ? finiteNumber(config.superAggressiveCategoryQueryMinimumTimeoutMs, 2200)
        : finiteNumber(config.categoryQueryMinimumTimeoutMs, 1800);
    const baseMinimum = Math.max(1500, configuredMinimum);
    const ceiling = Math.max(baseMinimum, finiteNumber(config.categoryQueryTimeoutMs, 4500));
    const minimum = Math.min(ceiling, baseMinimum + readTimeoutTailBoostMs());
    if (requestLatencySamples < 5 || !(requestLatencyEmaMs > 0)) return ceiling;
    return Math.max(minimum, Math.min(
        ceiling,
        Math.round(requestLatencyEmaMs * 4 + 600),
    ));
}

function adaptiveBuyRequestTimeoutMs() {
    const minimum = Math.max(
        1500,
        finiteNumber(config.buyRequestMinimumTimeoutMs, 2000),
    );
    const ceiling = Math.max(minimum, finiteNumber(config.buyRequestTimeoutMs, 5000));
    if (requestLatencySamples < 5 || !(requestLatencyEmaMs > 0)) return ceiling;
    // A BUY response timeout does not imply failure; pendingBuy inventory
    // reconciliation remains authoritative. This timeout only prevents the JS
    // request promise from blocking the scanner for many seconds.
    return Math.max(minimum, Math.min(
        ceiling,
        Math.round(requestLatencyEmaMs * 5 + 700),
    ));
}

function adaptiveRapidWatchIntervalMs() {
    const configured = Math.max(50, finiteNumber(config.itemRapidWatchRecheckMs, 75));
    const base = requestLatencySamples < 5 || !(requestLatencyEmaMs > 0)
        ? configured
        : Math.max(50, Math.min(configured, Math.round(requestLatencyEmaMs * 0.25)));
    if (!auctionDungeonActive()) return base;
    let floor = Math.max(50, finiteNumber(config.dungeonBackgroundRapidWatchMinimumMs, 150));
    if (combatPeerCoexistenceSnapshot().active)
        floor = Math.max(floor, finiteNumber(config.dungeonCombatPeerRapidWatchMinimumMs, 180));
    const pressure = autoLootDungeonPressureLevel();
    if (pressure >= 2) floor = Math.max(floor, finiteNumber(config.dungeonAutoLootBusyRapidWatchMinimumMs, 220));
    else if (pressure === 1) floor = Math.max(floor, finiteNumber(config.dungeonAutoLootActiveRapidWatchMinimumMs, 180));
    return Math.max(base, floor);
}

function adaptivePurchaseDeliveryTimeoutMs() {
    const minimum = Math.max(
        2000,
        finiteNumber(config.purchaseDeliveryMinimumTimeoutMs, 2200),
    );
    const maximum = Math.max(
        minimum,
        finiteNumber(config.purchaseDeliveryMaximumTimeoutMs, 10000),
    );
    const configured = Math.max(
        minimum,
        Math.min(maximum, finiteNumber(config.purchaseDeliveryTimeoutMs, 8000)),
    );
    if (requestLatencySamples < 5 || !(requestLatencyEmaMs > 0)) return configured;

    // Delivery is usually much faster than the request timeout. Give inventory
    // replication several observed RTTs plus the partial-fill grace window, but
    // do not let an unfilled order monopolize the single pending-buy slot.
    const adaptive = Math.round(
        requestLatencyEmaMs * 4 +
        Math.max(900, finiteNumber(config.partialDeliveryGraceMs, 1500)),
    );
    return Math.max(minimum, Math.min(maximum, adaptive));
}

async function reserveRequestDispatch(label, requestGeneration, dispatchGuard = undefined) {
    ++requestDispatchReservationsActive;
    let releaseReservation;
    const myTurn = new Promise(resolve => { releaseReservation = resolve; });
    const previousTurn = requestDispatchReservationTail;
    requestDispatchReservationTail = myTurn;
    ++state.stats.requestDispatchReservations;
    const queuedAt = Date.now();
    try {
        await previousTurn;
        if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
        const waitStartedAt = Date.now();
        if (autoLootMarketOwnershipActive(waitStartedAt)) {
            ++state.stats.dungeonAutoLootListAllInterlockHolds;
            throw cancelledRequest(`${label} Auto Loot List-All ownership`);
        }
        const priorityExactFastLane = nonSuperPriorityExactReadFastLaneEligible(label, waitStartedAt);
        const lastDispatchAt = marketRequestDispatchTimes.length
            ? finiteNumber(marketRequestDispatchTimes[marketRequestDispatchTimes.length - 1])
            : 0;
        const ordinaryPaceWait = Math.max(0, nextRequestAt - waitStartedAt);
        const priorityPaceWait = priorityExactFastLane && lastDispatchAt > 0
            ? Math.max(0, lastDispatchAt + nonSuperPriorityExactReadGapMs() - waitStartedAt)
            : ordinaryPaceWait;
        const paceWait = priorityExactFastLane ? Math.min(ordinaryPaceWait, priorityPaceWait) : ordinaryPaceWait;
        const superBudgetWait = superAggressiveRequestBudgetRequiredWaitMs(waitStartedAt);
        const nonSuperReadBudgetWait = nonSuperReadBudgetRequiredWaitMs(label, waitStartedAt);
        const autoLootOwnershipWait = autoLootMarketOwnershipWaitMs(waitStartedAt);
        const autoLootMarketReadWait = autoLootMarketReadOverlapWaitMs(label, waitStartedAt);
        // A55.92: a request can sit behind pacing long enough for an Auto Loot peer
        // to disappear/reload after pacedRequest's pre-queue discovery check. Fold
        // discovery into the serialized governor so actual dispatch is revalidated.
        const autoLootPeerDiscoveryWait = autoLootPeerDiscoveryDispatchWaitMs(label, waitStartedAt);
        const wait = Math.max(paceWait, superBudgetWait, nonSuperReadBudgetWait, autoLootOwnershipWait, autoLootMarketReadWait, autoLootPeerDiscoveryWait);
        const priorityExactActuallyAccelerated = Boolean(priorityExactFastLane && wait < ordinaryPaceWait);
        if (waitStartedAt - queuedAt > 1 || wait > 0) ++state.stats.requestDispatchReservationWaits;
        if (superBudgetWait > 0) { ++state.stats.superAggressiveRequestBudgetWaits; state.stats.superAggressiveRequestBudgetWaitMs += superBudgetWait; }
        if (nonSuperReadBudgetWait > 0) { ++state.stats.nonSuperReadBudgetWaits; state.stats.nonSuperReadBudgetWaitMs += nonSuperReadBudgetWait; }
        if (autoLootOwnershipWait > 0) { ++state.stats.dungeonAutoLootListAllInterlockHolds; state.stats.dungeonAutoLootListAllInterlockWaitMs += autoLootOwnershipWait; }
        if (autoLootMarketReadWait > 0) { ++state.stats.dungeonAutoLootMarketReadOverlapHolds; state.stats.dungeonAutoLootMarketReadOverlapWaitMs += autoLootMarketReadWait; }
        if (autoLootPeerDiscoveryWait > 0) { ++state.stats.dungeonAutoLootPeerDiscoveryDispatchHolds; state.stats.dungeonAutoLootPeerDiscoveryDispatchWaitMs += autoLootPeerDiscoveryWait; }
        if (wait > 0) await delay(wait);
        if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
        while (true) {
            const strictNow = Date.now();
            if (!auctionDungeonMarketTradingAllowed(strictNow)) throw cancelledRequest(`${label} lobby profile dungeon hold`);
            if (autoLootMarketOwnershipActive(strictNow)) {
                ++state.stats.dungeonAutoLootListAllInterlockHolds;
                throw cancelledRequest(`${label} Auto Loot List-All ownership`);
            }
            const strictLastDispatchAt = marketRequestDispatchTimes.length
                ? finiteNumber(marketRequestDispatchTimes[marketRequestDispatchTimes.length - 1]) : 0;
            const strictOrdinaryPaceWait = Math.max(0, nextRequestAt - strictNow);
            const strictPriorityPaceWait = priorityExactFastLane && strictLastDispatchAt > 0
                ? Math.max(0, strictLastDispatchAt + nonSuperPriorityExactReadGapMs() - strictNow)
                : strictOrdinaryPaceWait;
            const strictPaceWait = priorityExactFastLane ? Math.min(strictOrdinaryPaceWait, strictPriorityPaceWait) : strictOrdinaryPaceWait;
            const strictSuperBudgetWait = superAggressiveRequestBudgetRequiredWaitMs(strictNow);
            const strictNonSuperBudgetWait = nonSuperReadBudgetRequiredWaitMs(label, strictNow);
            const strictAutoLootOwnershipWait = autoLootMarketOwnershipWaitMs(strictNow);
            const strictAutoLootMarketReadWait = autoLootMarketReadOverlapWaitMs(label, strictNow);
            const strictAutoLootPeerDiscoveryWait = autoLootPeerDiscoveryDispatchWaitMs(label, strictNow);
            const strictWait = Math.max(strictPaceWait, strictSuperBudgetWait, strictNonSuperBudgetWait, strictAutoLootOwnershipWait, strictAutoLootMarketReadWait, strictAutoLootPeerDiscoveryWait);
            if (strictWait <= 0) break;
            ++state.stats.requestGovernorStrictRechecks;
            if (strictSuperBudgetWait > 0) { ++state.stats.superAggressiveRequestBudgetWaits; state.stats.superAggressiveRequestBudgetWaitMs += strictSuperBudgetWait; }
            if (strictNonSuperBudgetWait > 0) { ++state.stats.nonSuperReadBudgetWaits; state.stats.nonSuperReadBudgetWaitMs += strictNonSuperBudgetWait; }
            if (strictAutoLootOwnershipWait > 0) { ++state.stats.dungeonAutoLootListAllInterlockHolds; state.stats.dungeonAutoLootListAllInterlockWaitMs += strictAutoLootOwnershipWait; }
            if (strictAutoLootMarketReadWait > 0) { ++state.stats.dungeonAutoLootMarketReadOverlapHolds; state.stats.dungeonAutoLootMarketReadOverlapWaitMs += strictAutoLootMarketReadWait; }
            if (strictAutoLootPeerDiscoveryWait > 0) { ++state.stats.dungeonAutoLootPeerDiscoveryDispatchHolds; state.stats.dungeonAutoLootPeerDiscoveryDispatchWaitMs += strictAutoLootPeerDiscoveryWait; }
            await delay(strictWait);
            if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
            if (requestGeneration !== networkGeneration) throw cancelledRequest(label);
            if (dispatchGuard && !dispatchGuard()) throw cancelledRequest(label);
        }
        if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
        if (requestGeneration !== networkGeneration) throw cancelledRequest(label);
        if (dispatchGuard && !dispatchGuard()) throw cancelledRequest(label);
        if (!auctionDungeonMarketTradingAllowed()) throw cancelledRequest(`${label} lobby profile dungeon hold`);
        if (autoLootMarketOwnershipActive()) throw cancelledRequest(`${label} Auto Loot List-All ownership changed at dispatch`);
        const dispatchedAt = Date.now();
        nextRequestAt = dispatchedAt + effectiveRequestGapMs(dispatchedAt);
        if (nonSuperPriorityExactReadLabel(label) && !superAggressiveModeActive()) {
            if (priorityExactActuallyAccelerated) ++state.stats.nonSuperPriorityExactReadFastDispatches;
            else ++state.stats.nonSuperPriorityExactReadNormalDispatches;
        }
        recordMarketMutationDispatch(label, dispatchedAt);
        recordMarketReadDispatch(label, dispatchedAt);
        recordMarketRequestDispatch(dispatchedAt);
        return dispatchedAt;
    } finally {
        requestDispatchReservationsActive = Math.max(0, requestDispatchReservationsActive - 1);
        try { releaseReservation(); } catch (_) {}
    }
}

async function reservePacedRequestDispatch(
    label,
    requestGeneration,
    dispatchGuard = undefined,
) {
    if (!marketMutationKindForLabel(label))
        return reserveRequestDispatch(label, requestGeneration, dispatchGuard);

    // A55.37 priority ordering happens BEFORE entering the mutation FIFO. This lets
    // a strong BUY that is already in final exact challenge claim the next mutation
    // turn without shortening the 3.1s hard gap or preempting an in-flight mutation.
    await waitForStrongBuyMutationRunway(label, requestGeneration, dispatchGuard);
    if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);

    ++marketMutationReservationsActive;
    let releaseMutationReservation;
    const myTurn = new Promise(resolve => { releaseMutationReservation = resolve; });
    const previousTurn = marketMutationReservationTail;
    marketMutationReservationTail = myTurn;
    try {
        await previousTurn;
        if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
        if (autoLootMarketOwnershipActive()) {
            ++state.stats.dungeonAutoLootListAllInterlockHolds;
            throw cancelledRequest(`${label} Auto Loot List-All ownership`);
        }
        let mutationSleepPasses = 0;
        while (true) {
            if (autoLootMarketOwnershipActive()) {
                ++state.stats.dungeonAutoLootListAllInterlockHolds;
                throw cancelledRequest(`${label} Auto Loot List-All ownership`);
            }
            const mutationWait = marketMutationRequiredWaitMs(label, Date.now());
            if (mutationWait <= 0) break;
            ++state.stats.marketMutationHardGapWaits;
            state.stats.marketMutationHardGapWaitMs += mutationWait;
            if (mutationSleepPasses > 0) ++state.stats.marketMutationHardGapStrictRechecks;
            ++mutationSleepPasses;
            await delay(mutationWait);
            if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
            if (requestGeneration !== networkGeneration) throw cancelledRequest(label);
            if (dispatchGuard && !dispatchGuard()) throw cancelledRequest(label);
        }
        // A55.18: the loop condition is the final mutation-gap check at the actual
        // handoff boundary. The mutation reservation remains held throughout, so
        // no peer mutation can race between the successful check and the global
        // dispatch lane. Early timer wakeups simply produce another loop pass.
        if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
        if (requestGeneration !== networkGeneration) throw cancelledRequest(label);
        if (dispatchGuard && !dispatchGuard()) throw cancelledRequest(label);
        return reserveRequestDispatch(label, requestGeneration, dispatchGuard);
    } finally {
        marketMutationReservationsActive = Math.max(0, marketMutationReservationsActive - 1);
        try { releaseMutationReservation(); } catch (_) {}
    }
}

async function pacedRequest(
    label,
    operation,
    timeoutMs = config.requestTimeoutMs,
    dispatchGuard = undefined,
) {
    // Every network request belongs to the connection generation that existed
    // when it was scheduled. A disconnect bumps the generation; requests waiting
    // behind pacing are then cancelled instead of firing immediately after login.
    if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
    // A55.90: D load order can start Auction before Auto Loot registers its
    // lightweight peer. Hold only outbound market-book/mutation dispatches during
    // the already-bounded startup/reacquire discovery grace. Authority refreshes
    // are excluded by autoLootPeerDiscoveryDispatchWaitMs().
    let peerDiscoveryPasses = 0;
    while (true) {
        const peerDiscoveryWait = autoLootPeerDiscoveryDispatchWaitMs(label, Date.now());
        if (peerDiscoveryWait <= 0) break;
        ++state.stats.dungeonAutoLootPeerDiscoveryDispatchHolds;
        state.stats.dungeonAutoLootPeerDiscoveryDispatchWaitMs += peerDiscoveryWait;
        ++peerDiscoveryPasses;
        await delay(peerDiscoveryWait);
        if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
        if (peerDiscoveryPasses >= 64) break; // bounded well beyond the 6s/250ms maximum expected pass count
    }
    await yieldToDungeonAutoLoot(label);
    if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
    const requestGeneration = networkGeneration;
    const dispatchedAt = await reservePacedRequestDispatch(
        label,
        requestGeneration,
        dispatchGuard,
    );
    if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
    if (auctionDungeonActive()) {
        const dungeonMutationKind = marketMutationKindForLabel(label);
        if (dungeonMutationKind) {
            ++state.stats.dungeonBackgroundMutationDispatches;
            if (dungeonMutationKind === 'BUY') ++state.stats.dungeonBackgroundBuyDispatches;
            else if (dungeonMutationKind === 'LIST') ++state.stats.dungeonBackgroundListDispatches;
            else if (dungeonMutationKind === 'COLLECT') ++state.stats.dungeonBackgroundCollectDispatches;
        } else {
            ++state.stats.dungeonBackgroundReadDispatches;
        }
    }
    // A55.19: background writes still pass through the historical release hook,
    // but sticky F8 ownership now makes that hook a no-op while the operator has
    // explicitly requested the cursor.  Reads and writes may proceed without
    // silently stealing the pointer; only F8/Release Mouse or real lobby teardown
    // relinquishes the lease.
    releaseOperatorMouseForBackgroundWrite(label);
    let requestCounted = false;
    let activeRequestClass = '';
    try {
        ++activeNetworkRequests;
        requestCounted = true;
        if (marketMutationKindForLabel(label)) {
            ++activeNetworkMutationRequests;
            activeRequestClass = 'MUTATION';
        } else {
            ++activeNetworkReadRequests;
            activeRequestClass = 'READ';
        }
        const result = await withTimeout(Promise.resolve().then(operation), label, timeoutMs);
        if (auctionRuntimeContinuationBlocked()) throw cancelledRequest(`${label} runtime ownership changed`);
        // A13: stale pre-disconnect requests can settle after the new world is up.
        // Cancel them before latency accounting so they never inflate the live EMA.
        if (requestGeneration !== networkGeneration) throw cancelledRequest(label);
        observeRequestLatency(Date.now() - dispatchedAt);
        consecutiveErrors = 0;
        return result;
    } catch (error) {
        if (requestWasCancelled(error)) throw error;
        if (isServerFrequencyLimitError(error)) {
            ++state.stats.serverFrequencyLimitSignals;
            const mutationGuarded = activateMarketMutationExplicitFrequencyGuard(
                label,
                error,
                Date.now(),
            );
            // A read-frequency signal gets only a short global pause. Mutation
            // signals instead use the dedicated temporary write guard above.
            if (!mutationGuarded)
                backoffUntil = Math.max(backoffUntil, Date.now() + 750);
            consecutiveErrors = 0;
            throw error;
        }
        if (isNetworkDisconnectError(error)) {
            ++state.stats.networkRequestDisconnectErrors;
            cancelSuperAggressiveReadAhead(`network disconnect: ${label}`);
            markNetworkDisconnected(`request failed: ${label}`, error);
            throw error;
        }
        if (isRequestTimeoutError(error)) {
            lastRequestTimeoutAt = Date.now();
            ++state.stats.requestTimeouts;
            // Market reads are side-effect free. Recover quickly instead of
            // imposing the generic exponential backoff on the entire scanner.
            if (/^Exact-affix average /i.test(String(label))) {
                consecutiveErrors = 0;
                backoffUntil = Math.max(
                    backoffUntil,
                    Date.now() + Math.max(0, finiteNumber(config.exactQueryTimeoutBackoffMs, 500)),
                );
                throw error;
            }
            if (/^Auction category /i.test(String(label))) {
                consecutiveErrors = 0;
                backoffUntil = Math.max(
                    backoffUntil,
                    Date.now() + Math.max(0, finiteNumber(config.categoryQueryTimeoutBackoffMs, 250)),
                );
                throw error;
            }
            // BUY/LIST requests are side-effect ambiguous, but both paths already
            // reconcile authoritative inventory state before retrying. Do not
            // freeze the whole scanner behind generic exponential backoff.
            if (/^(Buy|List)\s/i.test(String(label))) {
                consecutiveErrors = 0;
                throw error;
            }
        }
        ++consecutiveErrors;
        const exponent = Math.min(consecutiveErrors - 1, 6);
        const pause = Math.min(
            finiteNumber(config.errorBackoffMaximumMs, 60000),
            finiteNumber(config.errorBackoffBaseMs, 2500) * Math.pow(2, exponent),
        );
        backoffUntil = Math.max(backoffUntil, Date.now() + pause);
        throw error;
    } finally {
        if (activeRequestClass === 'MUTATION')
            activeNetworkMutationRequests = Math.max(0, activeNetworkMutationRequests - 1);
        else if (activeRequestClass === 'READ')
            activeNetworkReadRequests = Math.max(0, activeNetworkReadRequests - 1);
        if (requestCounted)
            activeNetworkRequests = Math.max(0, activeNetworkRequests - 1);
        if (operatorMouseInteractive && backgroundWriteLabel(label))
            scheduleOperatorCursorRecoveryAfterUiEvent(`request settled: ${label}`);
    }
}

function constantFloat(id, fallback) {
    try {
        const value = CfgMgr.getDynamicData(ConstantCfg, id)?.paraFloat?.[0];
        return finiteNumber(value, fallback);
    } catch (_) {
        return fallback;
    }
}

function constantInt(id, fallback) {
    try {
        const value = CfgMgr.getDynamicData(ConstantCfg, id)?.paraInt?.[0];
        return Math.floor(finiteNumber(value, fallback));
    } catch (_) {
        return fallback;
    }
}

function marketRules() {
    return {
        taxRatio: constantFloat(EConstant.Trade_Tax_Ratio, 0.10),
        depositRatio: constantFloat(EConstant.Trade_Deposit_Ratio, 0.03),
        maximumDeposit: constantInt(EConstant.Trade_Max_Deposit, 1000),
    };
}

function saleTax(unitPrice, quantity = 1) {
    const gross = Math.max(0, finiteNumber(unitPrice)) * positiveInteger(quantity);
    return Math.ceil(gross * marketRules().taxRatio);
}

function listingDeposit(unitPrice, quantity = 1) {
    const gross = Math.max(0, finiteNumber(unitPrice)) * positiveInteger(quantity);
    const rules = marketRules();
    return Math.min(Math.ceil(gross * rules.depositRatio), rules.maximumDeposit);
}

function currencyGoldAuthoritySnapshot() {
    const info = safeProperty(currencyModel, 'currenciesInfo');
    if (!info) {
        return {
            authoritative: false,
            gold: Number.isFinite(lastObservedGold) ? lastObservedGold : 0,
            source: 'CURRENCY_INFO_UNAVAILABLE',
            cfgIdPresent: false,
        };
    }

    // Mistfall source authority:
    // CurrenciesInfo.getCurrencyCount(id) returns 0 when getCurrencyItem(id) is
    // absent, so a raw numeric zero alone cannot distinguish "real zero" from
    // "the currency table has not been hydrated in this instance yet."
    const currencyItem = safeCall(info, 'getCurrencyItem', 101);
    if (!currencyItem) {
        return {
            authoritative: false,
            gold: Number.isFinite(lastObservedGold) ? lastObservedGold : 0,
            source: 'CFG_101_ABSENT',
            cfgIdPresent: false,
        };
    }

    const rawCount = safeProperty(safeProperty(currencyItem, 'currencyCount'), 'v');
    const numericCount = Number(rawCount);
    if (!Number.isFinite(numericCount) || numericCount < 0) {
        return {
            authoritative: false,
            gold: Number.isFinite(lastObservedGold) ? lastObservedGold : 0,
            source: 'CFG_101_INVALID',
            cfgIdPresent: true,
        };
    }

    const gold = Math.max(0, Math.floor(numericCount));
    return {
        authoritative: true,
        gold,
        source: 'CURRENCY_INFO_CFG_101',
        cfgIdPresent: true,
    };
}

function currentGold() {
    const authority = currencyGoldAuthoritySnapshot();
    if (authority.authoritative) {
        lastObservedGold = authority.gold;
        walletAuthorityLastSource = authority.source;
        if (!walletAuthorityFirstProvenAt) walletAuthorityFirstProvenAt = Date.now();
        return authority.gold;
    }
    // Never overwrite a previously proven balance with CurrenciesInfo's
    // ambiguous absent-entry zero fallback.
    if (Number.isFinite(lastObservedGold)) {
        ++state.stats.walletAuthorityFalseZeroAvoids;
        return lastObservedGold;
    }
    return 0;
}

function stallCapacityAuthoritySnapshot() {
    if (!tradeModel) return {
        observed: 0,
        maximum: 0,
        provisional: true,
        source: 'TRADE_MODEL_UNAVAILABLE',
    };
    let observed = 0;
    let maximum = 0;
    try { observed = Math.max(0, Math.floor(finiteNumber(tradeModel.getStallNum?.()))); } catch (_) {}
    try { maximum = Math.max(0, Math.floor(finiteNumber(tradeModel.getMaxStallNum?.()))); } catch (_) {}
    const provisional = Boolean(
        DUNGEON_COEXIST_PROFILE && auctionDungeonActive() &&
        observed > 0 && maximum > observed
    );
    return {
        observed,
        maximum,
        provisional,
        source: provisional
            ? 'DUNGEON_SOURCE_MINIMUM_POSSIBLY_UNHYDRATED'
            : 'TRADE_MODEL_GET_STALL_NUM',
    };
}

async function ensureWalletAuthority(now = Date.now()) {
    const current = currencyGoldAuthoritySnapshot();
    if (current.authoritative) {
        lastObservedGold = current.gold;
        walletAuthorityLastSource = current.source;
        if (!walletAuthorityFirstProvenAt) walletAuthorityFirstProvenAt = now;
        if (!Number.isFinite(runtimeGoldAtStart)) runtimeGoldAtStart = current.gold;
        return true;
    }

    if (!config.walletAuthorityRequiredBeforeAutonomousMarket)
        return true;
    if (!config.walletAuthorityRefreshEnabled)
        return false;
    if (!currencyModel || typeof safeProperty(currencyModel, 'requestCurrencyInfo') !== 'function')
        return false;
    if (walletAuthorityRefreshInFlight)
        return false;

    const retryMs = Math.max(250, finiteNumber(config.walletAuthorityRefreshRetryMs, 1500));
    if (walletAuthorityLastRefreshAt && now - walletAuthorityLastRefreshAt < retryMs)
        return false;

    walletAuthorityLastRefreshAt = now;
    walletAuthorityRefreshInFlight = true;
    ++state.stats.walletAuthorityRefreshAttempts;
    const beforeGold = Number.isFinite(lastObservedGold) ? lastObservedGold : undefined;
    try {
        await pacedRequest(
            'Wallet currency authority refresh',
            () => currencyModel.requestCurrencyInfo(),
            Math.max(2000, finiteNumber(config.walletAuthorityRefreshTimeoutMs, 5000)),
            () => Boolean(currencyModel) && !disposed,
        );
        const after = currencyGoldAuthoritySnapshot();
        if (!after.authoritative) {
            ++state.stats.walletAuthorityRefreshHolds;
            walletAuthorityLastSource = after.source;
            return false;
        }
        lastObservedGold = after.gold;
        walletAuthorityLastSource = after.source;
        if (!walletAuthorityFirstProvenAt) walletAuthorityFirstProvenAt = Date.now();
        if (!Number.isFinite(runtimeGoldAtStart)) {
            runtimeGoldAtStart = after.gold;
            ++state.stats.walletAuthorityLatePromotions;
        }
        ++state.stats.walletAuthorityRefreshSuccesses;
        log.success('AUCTION WALLET AUTHORITY PROVEN', {
            gold: after.gold,
            source: after.source,
            previousObservedGold: beforeGold,
            runtimeStartingGold: runtimeGoldAtStart,
            runtimeProfile: AUCTION_RUNTIME_PROFILE,
            dungeonActive: auctionDungeonActive(),
            policy: 'CFG_101_PRESENCE_REQUIRED; REAL ZERO ALLOWED',
        });
        return true;
    } catch (error) {
        if (!requestWasCancelled(error)) {
            ++state.stats.walletAuthorityRefreshErrors;
            log.warn('AUCTION WALLET AUTHORITY REFRESH HELD', {
                error: errorText(error),
                runtimeProfile: AUCTION_RUNTIME_PROFILE,
                dungeonActive: auctionDungeonActive(),
                nextRetryMs: retryMs,
            });
        }
        return false;
    } finally {
        walletAuthorityRefreshInFlight = false;
    }
}

function hoardBankrollSafetySnapshot(goldValue = currentGold(), updateAnchor = true) {
    const gold = Math.max(0, Math.floor(finiteNumber(goldValue)));
    const active = Boolean(
        config.hoardBankrollCapacityEnabled &&
        operatorDesiredHoard() &&
        !operatorDesiredReadOnlyAllMarket()
    );
    if (!active) return { active: false, gold, anchorGold: 0, protectedGold: 0, headroom: gold };

    let anchorGold = Math.max(0, Math.floor(finiteNumber(state.hoardBudgetAnchorGold)));
    if (anchorGold <= 0) {
        anchorGold = gold;
        if (updateAnchor) {
            state.hoardBudgetAnchorGold = anchorGold;
            state.hoardBudgetAnchorAt = Date.now();
            if (state.stats) ++state.stats.hoardBudgetAnchorResets;
        }
    } else if (gold > anchorGold) {
        anchorGold = gold;
        if (updateAnchor) {
            state.hoardBudgetAnchorGold = anchorGold;
            state.hoardBudgetAnchorAt = Date.now();
            if (state.stats) ++state.stats.hoardBudgetAnchorRaises;
        }
    }

    const reserveRatio = Math.max(
        0,
        Math.min(0.95, Math.max(
            finiteNumber(config.operatorHardReserveRatio, 0.10),
            finiteNumber(config.hoardBankrollReserveRatio, 0.15),
            finiteNumber(config.dynamicReserveRatio, 0.15),
            config.highRiskHighRewardMode ? finiteNumber(config.highRiskReserveRatio, 0.15) : 0
        ))
    );
    const minimumReserve = Math.max(
        Math.floor(finiteNumber(config.operatorHardReserveMinimum, 1500)),
        Math.floor(finiteNumber(config.dynamicMinimumReserve, 1500)),
        Math.floor(finiteNumber(config.hoardBankrollMinimumReserve, 1500))
    );
    const protectedGold = Math.min(
        anchorGold,
        Math.max(minimumReserve, Math.floor(anchorGold * reserveRatio))
    );
    return {
        active: true,
        gold,
        anchorGold,
        protectedGold,
        reserveRatio,
        minimumReserve,
        headroom: Math.max(0, gold - protectedGold),
    };
}

function sessionSpentForBudget() {
    const spent = Math.max(0, finiteNumber(state.sessionSpent));
    if (!(config.hoardBankrollCapacityEnabled && operatorDesiredHoard() && !operatorDesiredReadOnlyAllMarket()))
        return spent;
    const base = Math.max(0, Math.min(spent, finiteNumber(state.hoardBudgetAnchorSessionSpentBase)));
    return Math.max(0, spent - base);
}

function sessionBuyRequestsForBudget() {
    const requests = Math.max(0, finiteNumber(state.sessionBuyRequests));
    if (!(config.hoardBankrollCapacityEnabled && operatorDesiredHoard() && !operatorDesiredReadOnlyAllMarket()))
        return requests;
    const base = Math.max(0, Math.min(requests, finiteNumber(state.hoardBudgetAnchorBuyRequestsBase)));
    return Math.max(0, requests - base);
}

function budgetSnapshot(goldValue = currentGold()) {
    const gold = Math.max(0, Math.floor(finiteNumber(goldValue)));
    const hoardMode = Boolean(
        config.hoardBankrollCapacityEnabled &&
        operatorDesiredHoard() &&
        !operatorDesiredReadOnlyAllMarket()
    );
    const hoardSafety = hoardMode ? hoardBankrollSafetySnapshot(gold) : undefined;
    if (!config.dynamicBudgetEnabled) {
        const hardReserve = Math.min(
            gold,
            Math.max(
                Math.floor(finiteNumber(config.operatorHardReserveMinimum, 1500)),
                Math.floor(gold * Math.max(0, Math.min(0.95,
                    finiteNumber(config.operatorHardReserveRatio, 0.10)))),
                Math.max(0, Math.floor(finiteNumber(config.cashReserve))),
                hoardMode ? Math.max(0, Math.floor(finiteNumber(hoardSafety?.protectedGold))) : 0,
            ),
        );
        const spendable = Math.max(0, gold - hardReserve);
        const hardSingleCap = Math.floor(
            gold * Math.max(0, Math.min(0.90,
                finiteNumber(config.operatorHardSinglePurchaseRatio, 0.35)))
        );
        const maximumSinglePurchase = Math.max(0, Math.min(
            spendable,
            hardSingleCap,
            Math.floor(finiteNumber(config.maximumSinglePurchase)),
        ));
        return {
            mode: 'FIXED_SAFE',
            gold,
            reserve: hardReserve,
            spendable,
            maximumUnitBuyPrice: Math.max(0, Math.min(
                maximumSinglePurchase,
                Math.floor(finiteNumber(config.maximumUnitBuyPrice)),
            )),
            maximumSinglePurchase,
            maximumSpendPerSession: Math.max(0, Math.min(
                hoardMode
                    ? Math.max(0, finiteNumber(hoardSafety?.anchorGold) - finiteNumber(hoardSafety?.protectedGold))
                    : spendable,
                Math.floor(finiteNumber(config.maximumSpendPerSession)),
            )),
            maximumBuyRequestsPerSession: positiveInteger(config.maximumBuyRequestsPerSession),
            maximumActivePositions: hoardMode
                ? Math.max(1, positiveInteger(config.hoardEmergencyTrackedPositionMaximum, 96))
                : positiveInteger(config.maximumActivePositions),
            hoardSafety,
            tier: 'fixed-safe',
        };
    }

    const highRisk = Boolean(config.highRiskHighRewardMode);
    const reserveRatio = Math.max(
        finiteNumber(config.operatorHardReserveRatio, 0.10),
        highRisk
            ? finiteNumber(config.highRiskReserveRatio, config.dynamicReserveRatio)
            : finiteNumber(config.dynamicReserveRatio, 0.50),
    );
    const singlePurchaseRatio = Math.min(
        finiteNumber(config.operatorHardSinglePurchaseRatio, 0.35),
        highRisk
            ? finiteNumber(config.highRiskSinglePurchaseRatio, config.dynamicSinglePurchaseRatio)
            : finiteNumber(config.dynamicSinglePurchaseRatio, 0.25),
    );
    const sessionSpendRatio = highRisk
        ? finiteNumber(config.highRiskSessionSpendRatio, config.dynamicSessionSpendRatio)
        : finiteNumber(config.dynamicSessionSpendRatio, 0.50);
    const proportionalReserve = Math.floor(
        gold * Math.max(0, Math.min(0.95, reserveRatio))
    );
    const reserve = Math.min(
        gold,
        Math.max(
            Math.max(
                Math.floor(finiteNumber(config.operatorHardReserveMinimum, 1500)),
                Math.max(0, Math.floor(finiteNumber(config.dynamicMinimumReserve, 500))),
            ),
            proportionalReserve,
            hoardMode ? Math.max(0, Math.floor(finiteNumber(hoardSafety?.protectedGold))) : 0,
        ),
    );
    const spendable = Math.max(0, gold - reserve);
    const proportionalSingle = Math.floor(
        gold * Math.max(0, Math.min(0.90, singlePurchaseRatio))
    );
    const maximumSinglePurchase = Math.max(0, Math.min(
        spendable,
        proportionalSingle,
        Math.floor(finiteNumber(config.maximumSinglePurchase, Number.MAX_SAFE_INTEGER)),
    ));
    const maximumUnitBuyPrice = Math.max(0, Math.min(
        maximumSinglePurchase,
        Math.floor(finiteNumber(config.maximumUnitBuyPrice, Number.MAX_SAFE_INTEGER)),
    ));
    const maximumSpendPerSession = Math.max(0, Math.min(
        hoardMode
            ? Math.max(0, Math.floor(
                finiteNumber(hoardSafety?.anchorGold) - finiteNumber(hoardSafety?.protectedGold)
            ))
            : Math.floor(gold * Math.max(
                0,
                Math.min(1, sessionSpendRatio),
            )),
        Math.floor(finiteNumber(config.maximumSpendPerSession, Number.MAX_SAFE_INTEGER)),
    ));

    const tier = gold < 5000 ? 'micro' : gold < 20000 ? 'growing' : 'established';
    const tierRequests = highRisk
        ? positiveInteger(config.highRiskMaximumBuyRequestsPerSession, 100)
        : positiveInteger(config.maximumBuyRequestsPerSession, 100);
    const detectedStallCapacity = tradeModel
        ? Math.max(0, Math.floor(finiteNumber(tradeModel.getStallNum?.()))) : 0;
    const configuredActiveMaximum = highRisk
        ? positiveInteger(config.highRiskMaximumActivePositions, 24)
        : positiveInteger(config.maximumActivePositions, 24);
    const stagingAllowance = Math.max(0, positiveInteger(config.maximumStagedPositionsWhileStallFull, 8));
    const tierPositions = detectedStallCapacity > 0
        ? Math.min(configuredActiveMaximum, detectedStallCapacity + stagingAllowance)
        : configuredActiveMaximum;
    return {
        mode: 'DYNAMIC',
        gold,
        reserve,
        spendable,
        maximumUnitBuyPrice,
        maximumSinglePurchase,
        maximumSpendPerSession,
        maximumBuyRequestsPerSession: Math.min(
            positiveInteger(config.maximumBuyRequestsPerSession),
            tierRequests,
        ),
        maximumActivePositions: hoardMode
            ? Math.max(1, positiveInteger(config.hoardEmergencyTrackedPositionMaximum, 96))
            : Math.min(
                positiveInteger(config.maximumActivePositions),
                tierPositions,
            ),
        hoardSafety,
        tier,
    };
}

function itemConfig(cfgId) {
    try {
        return CfgMgr.getDynamicData(ItemAttrCfg, finiteNumber(cfgId));
    } catch (_) {
        return undefined;
    }
}

function itemName(cfgId) {
    const cfg = itemConfig(cfgId);
    try {
        const value = cfg && typeof cfg.name === 'function' ? cfg.name() : undefined;
        return value ? String(value) : `Item #${finiteNumber(cfgId)}`;
    } catch (_) {
        return `Item #${finiteNumber(cfgId)}`;
    }
}

function isEquipmentConfig(cfg) {
    return Boolean(cfg && (
        cfg.weaponType !== undefined ||
        cfg.armorType !== undefined ||
        finiteNumber(cfg.itemType) === finiteNumber(EItemType?.Weapon, -1001) ||
        finiteNumber(cfg.itemType) === finiteNumber(EItemType?.Armor, -1002)
    ));
}

function itemQualityValue(cfgId) {
    const cfg = itemConfig(cfgId);
    if (!cfg) return undefined;
    const candidates = [
        cfg.rarityId, cfg.rarity, cfg.qualityId, cfg.quality, cfg.gradeId, cfg.grade,
    ];
    for (let candidate of candidates) {
        try {
            if (typeof candidate === 'function') candidate = candidate.call(cfg);
        } catch (_) {
            continue;
        }
        if (candidate && typeof candidate === 'object')
            candidate = candidate.v ?? candidate.value ?? candidate.id ?? candidate;
        const value = finiteNumber(candidate, NaN);
        if (Number.isFinite(value)) return value;
    }
    return undefined;
}


const PRIORITY_RARITY_NAMES = Object.freeze({
    0: 'Tier 0', 1: 'Damaged', 2: 'Common', 3: 'Rare', 4: 'Excellent',
    5: 'Epic', 6: 'Legendary', 7: 'Holy', 8: 'Prismatic',
});

const PRIORITY_CATEGORY_ORDER = Object.freeze(['items','keys','gems','weapons','armor','accessories']);
const PRIORITY_CATEGORY_NAMES = Object.freeze({
    items: 'ITEMS', keys: 'KEYS', gems: 'GEMS', weapons: 'WEAPONS', armor: 'ARMOR', accessories: 'ACCESSORY',
});

function priorityCategoryDisplayName(category) {
    const key = String(category || '').toLowerCase();
    return PRIORITY_CATEGORY_NAMES[key] || key.toUpperCase() || 'ITEMS';
}

function hudCategoryVisualIdentity(category, selected = false, hovered = false) {
    const palette = {
        items:       { fill:'#23102EF2', active:'#542269F8', border:'#8C4BABFF', text:'#EEDDF7FF', accent:'#C56BEEFF' },
        keys:        { fill:'#332407F2', active:'#6B4A0CF8', border:'#C48B25FF', text:'#FFE5A6FF', accent:'#F0B94FFF' },
        gems:        { fill:'#082B31F2', active:'#0E5963F8', border:'#2BAAB7FF', text:'#C7FAFFFF', accent:'#57D9E7FF' },
        weapons:     { fill:'#351019F2', active:'#6E1B2BF8', border:'#B84562FF', text:'#FFD2DDFF', accent:'#F06484FF' },
        armor:       { fill:'#0A2238F2', active:'#124A78F8', border:'#377FBFFF', text:'#D5ECFFFF', accent:'#62ADF0FF' },
        accessories: { fill:'#35102FF2', active:'#701E60F8', border:'#B94B9EFF', text:'#FFD6F4FF', accent:'#ED72CFFF' },
    };
    const value = palette[String(category || '').toLowerCase()] || palette.items;
    return {
        fill: selected ? value.active : (hovered ? value.active : value.fill),
        border: selected ? value.accent : (hovered ? value.accent : value.border),
        text: value.text,
        accent: value.accent,
    };
}

function rarityDisplayName(value) {
    const rarity = Math.floor(finiteNumber(value));
    return PRIORITY_RARITY_NAMES[rarity] || `Rarity ${rarity}`;
}

function hudRarityVisualIdentity(value, selected = false, hovered = false) {
    const rarity = Math.floor(finiteNumber(value));
    const palette = {
        1: ['#38343CF2','#82798CFF','#D4CDD8FF','#AAA0B4FF'],
        2: ['#323238F2','#B9B9C1FF','#F1F1F5FF','#D6D6DDFF'],
        3: ['#0D2C1AF2','#2EB76AFF','#BDF4CFFF','#63D88DFF'],
        4: ['#0A2440F2','#318DDEFF','#C2E4FFFF','#5CB4F5FF'],
        5: ['#2B0E3CF2','#A74DD7FF','#EACBFAFF','#C36BF0FF'],
        6: ['#3A2209F2','#E69732FF','#FFE0A6FF','#F2B35BFF'],
        7: ['#3A340CF2','#E5D35BFF','#FFF5B6FF','#F0E37CFF'],
    };
    const [base,border,text,accent] = palette[rarity] || palette[2];
    return {
        fill: hovered ? base.replace('F2','FA') : base,
        border,
        text: selected ? text : text,
        accent,
    };
}

function priorityBuySelectedSet() {
    return new Set(Array.from(state.operatorSettings.priorityBuySelectedCfgIds || [])
        .map(value => Math.floor(finiteNumber(value))).filter(value => value > 0));
}

function priorityBuyTargetUnits(cfgId) {
    const id = Math.floor(finiteNumber(cfgId));
    const defaultUnits = Math.max(1, Math.floor(finiteNumber(config.prioritySmartBuyDefaultTargetUnits, 5)));
    const maximumUnits = Math.max(defaultUnits, Math.floor(finiteNumber(config.prioritySmartBuyMaximumTargetUnits, 99)));
    const raw = state.operatorSettings?.priorityBuyTargetUnitsByCfgId?.[String(id)];
    return Math.max(1, Math.min(maximumUnits, Math.floor(finiteNumber(raw, defaultUnits))));
}

function setPriorityBuyTargetUnits(cfgId, units, autoSelect = true) {
    const id = Math.floor(finiteNumber(cfgId));
    if (id <= 0 || !itemConfig(id)) return false;
    const defaultUnits = Math.max(1, Math.floor(finiteNumber(config.prioritySmartBuyDefaultTargetUnits, 5)));
    const maximumUnits = Math.max(defaultUnits, Math.floor(finiteNumber(config.prioritySmartBuyMaximumTargetUnits, 99)));
    const value = Math.max(1, Math.min(maximumUnits, Math.floor(finiteNumber(units, defaultUnits))));
    if (!state.operatorSettings.priorityBuyTargetUnitsByCfgId || typeof state.operatorSettings.priorityBuyTargetUnitsByCfgId !== 'object')
        state.operatorSettings.priorityBuyTargetUnitsByCfgId = {};
    state.operatorSettings.priorityBuyTargetUnitsByCfgId[String(id)] = value;
    if (autoSelect) {
        const selected = priorityBuySelectedSet();
        selected.add(id);
        state.operatorSettings.priorityBuySelectedCfgIds = Array.from(selected).sort((a,b)=>a-b).slice(0,256);
    }
    prioritySelectorFilteredCacheKey = '';
    persistOperatorSettings();
    state.lastAction = `${itemName(id)} Smart Buy target set to x${value}`;
    updateOperatorControlReadout();
    updateHud();
    return true;
}

function priorityBuyRunTargetUnits(cfgId) {
    const id = Math.floor(finiteNumber(cfgId));
    return Math.max(1, Math.floor(finiteNumber(prioritySmartBuyRunTargetUnitsByCfgId[String(id)], priorityBuyTargetUnits(id))));
}

function priorityBuyAcquiredUnits(cfgId) {
    const id = Math.floor(finiteNumber(cfgId));
    return Math.max(0, Math.floor(finiteNumber(prioritySmartBuyAcquiredUnitsByCfgId[String(id)])));
}

function priorityBuyRemainingUnits(cfgId) {
    return Math.max(0, priorityBuyRunTargetUnits(cfgId) - priorityBuyAcquiredUnits(cfgId));
}

function recordPrioritySmartBuyDelivery(cfgId, quantity, late = false) {
    const id = Math.floor(finiteNumber(cfgId));
    const delivered = Math.max(0, Math.floor(finiteNumber(quantity)));
    if (id <= 0 || delivered <= 0) return false;
    const before = priorityBuyAcquiredUnits(id);
    const target = priorityBuyRunTargetUnits(id);
    const after = Math.min(target, before + delivered);
    prioritySmartBuyAcquiredUnitsByCfgId[String(id)] = after;
    state.stats.prioritySmartBuyDeliveredUnits += Math.max(0, after - before);
    const newlySatisfied = before < target && after >= target;
    if (newlySatisfied) {
        prioritySmartBuySatisfiedCfgIds.add(id);
        ++state.stats.prioritySmartBuyDeliveredTargets;
        delete prioritySmartBuyNextProbeAtByCfgId[String(id)];
    }
    log.info('OMEGAB PRIORITY SMART BUY TARGET PROGRESS', {
        item: itemName(id), cfgId: id, delivered, acquired: after, target,
        remaining: Math.max(0, target-after), satisfied: newlySatisfied || after >= target, late: Boolean(late),
    });
    return newlySatisfied;
}

function setPriorityBuyTarget(cfgId, enabled = true) {
    const id = Math.floor(finiteNumber(cfgId));
    if (id <= 0 || !itemConfig(id)) return false;
    if (enabled && !validTradableConfig(id)) { hudControlToast(`${itemName(id)} is not Auction-House tradable`); return false; }
    const selected = priorityBuySelectedSet();
    if (enabled) {
        selected.add(id);
        if (!state.operatorSettings.priorityBuyTargetUnitsByCfgId || typeof state.operatorSettings.priorityBuyTargetUnitsByCfgId !== 'object')
            state.operatorSettings.priorityBuyTargetUnitsByCfgId = {};
        if (!(String(id) in state.operatorSettings.priorityBuyTargetUnitsByCfgId))
            state.operatorSettings.priorityBuyTargetUnitsByCfgId[String(id)] = Math.max(1, Math.floor(finiteNumber(config.prioritySmartBuyDefaultTargetUnits,5)));
    } else selected.delete(id);
    state.operatorSettings.priorityBuySelectedCfgIds = Array.from(selected).sort((a,b) => a-b).slice(0, 256);
    prioritySelectorFilteredCacheKey = '';
    persistOperatorSettings();
    state.lastAction = `${enabled ? 'Added' : 'Removed'} ${itemName(id)} ${enabled ? `x${priorityBuyTargetUnits(id)} to` : 'from'} Priority Smart Buy`;
    log.info('OMEGAB PRIORITY ITEM TARGET TOGGLED', {
        cfgId: id,
        item: itemName(id),
        selected: Boolean(enabled),
        targetUnits: priorityBuyTargetUnits(id),
        selectedCount: selected.size,
    });
    updateOperatorControlReadout();
    updateHud();
    return true;
}

function priorityBuyCatalog(force = false) {
    if (prioritySelectorCatalogCache && !force) return prioritySelectorCatalogCache;
    const rows = [];
    try {
        const dynamicMap = CfgMgr.getDynamicMap(ItemAttrCfg);
        const entries = dynamicMap && typeof dynamicMap.entries === 'function'
            ? Array.from(dynamicMap.entries()) : Object.entries(dynamicMap || {});
        const seen = new Set();
        for (const pair of entries) {
            const rawId = Array.isArray(pair) ? pair[0] : undefined;
            const cfg = Array.isArray(pair) ? pair[1] : undefined;
            const cfgId = Math.floor(finiteNumber(cfg?.id ?? cfg?.cfgId ?? rawId));
            if (cfgId <= 0 || seen.has(cfgId) || !cfg) continue;
            seen.add(cfgId);
            let name = '';
            try { name = typeof cfg.name === 'function' ? String(cfg.name() || '') : ''; } catch (_) {}
            if (!name) name = `Item #${cfgId}`;
            const filterProfile = itemFilterProfileForCfg(cfgId);
            const rarity = Math.max(0, Math.floor(finiteNumber(filterProfile.rarity)));
            const category = filterProfile.category;
            rows.push({
                cfgId, name, rarity, category,
                categoryName: priorityCategoryDisplayName(category),
                rarityName: PRIORITY_RARITY_NAMES[rarity] || `Rarity ${rarity}`,
                equipment: filterProfile.kind === 'equipment',
                tradable: validTradableConfig(cfgId),
                minPrice: Math.max(0, Math.floor(finiteNumber(cfg.minPrice))),
                maxPrice: Math.max(0, Math.floor(finiteNumber(cfg.maxPrice))),
                recommendedPrice: Math.max(0, Math.floor(finiteNumber(cfg.recommendedPrice))),
            });
        }
    } catch (error) {
        log.warn('PRIORITY BUY CATALOG BUILD FAILED; selector stays available', {
            error: String(error?.message || error).slice(0,180),
        });
    }
    rows.sort((a,b) => b.rarity-a.rarity || a.name.localeCompare(b.name) || a.cfgId-b.cfgId);
    prioritySelectorCatalogCache = rows;
    prioritySelectorFilteredCacheKey = '';
    ++state.stats.prioritySmartBuyCatalogBuilds;
    return rows;
}

function priorityBuyFilteredCatalog() {
    const q = String(prioritySelectorSearch || '').trim().toLowerCase();
    const rarities = Array.from(prioritySelectorRarityFilters).sort((a,b)=>a-b);
    const categories = Array.from(prioritySelectorCategoryFilters).sort();
    const selected = priorityBuySelectedSet();
    const key = `${q}|${rarities.join(',')}|${categories.join(',')}|${Array.from(selected).sort((a,b)=>a-b).join(',')}`;
    if (prioritySelectorFilteredCache && prioritySelectorFilteredCacheKey === key)
        return prioritySelectorFilteredCache;
    const terms = q.split(/\s+/).filter(Boolean);
    const rows = priorityBuyCatalog().filter(row => {
        if (!prioritySelectorCategoryFilters.has(String(row.category || 'items'))) return false;
        // Normal browsing stays organized around the user's T1-T7 model.  The
        // underlying source-backed catalog still contains every positive ItemAttrCfg
        // id; typing a name/cfgId is allowed to surface source rarities outside T1-T7
        // (currently T0/T8) so "all item IDs" remains literally searchable.
        if (row.rarity >= 1 && row.rarity <= 7) {
            if (!prioritySelectorRarityFilters.has(row.rarity)) return false;
        } else if (!terms.length) {
            return false;
        }
        if (!terms.length) return true;
        const hay = `${row.name.toLowerCase()} ${row.cfgId} ${String(row.categoryName || '').toLowerCase()} ${String(row.category || '')}`;
        return terms.every(term => hay.includes(term));
    }).sort((a,b) => b.rarity-a.rarity || a.name.localeCompare(b.name) || a.cfgId-b.cfgId);
    prioritySelectorFilteredCache = rows;
    prioritySelectorFilteredCacheKey = key;
    const pageSize = Math.max(5, positiveInteger(config.prioritySmartBuySelectorRows, 9));
    const maxPage = Math.max(0, Math.ceil(rows.length/pageSize)-1);
    prioritySelectorPage = Math.max(0, Math.min(prioritySelectorPage, maxPage));
    return rows;
}

function prioritySelectorPanelGeometry() {
    const hudX = Math.floor(finiteNumber(config.hudX, 300));
    const hudY = Math.floor(finiteNumber(config.hudY, 6));
    const controlX = hudX + 684;
    const gap = Math.max(12, Math.floor(finiteNumber(config.prioritySmartBuySelectorPanelGap, 18)));
    const requested = Math.max(560, Math.floor(finiteNumber(config.prioritySmartBuySelectorPanelWidth, 646)));
    // Left dashboard owns 646px; leave a deliberate gap before the right control deck.
    const w = Math.min(requested, Math.max(560, controlX - gap - (hudX + 18)));
    const x = hudX + 18;
    const y = hudY + 78;
    const h = Math.max(560, Math.floor(finiteNumber(config.hudHeight, 790)) - 102);
    return { x, y, w, h };
}

function openPriorityBuySelector(source = 'HUD PRIORITY ITEM TABLE', autoOpened = false) {
    if (disposed || shutdownRequested) return false;
    const catalog = priorityBuyCatalog(true);
    prioritySelectorOpen = true;
    prioritySelectorSearchFocused = true;
    for(const name of Object.keys(prioritySelectorControllerWasDown)) delete prioritySelectorControllerWasDown[name];
    prioritySelectorPage = 0;
    prioritySelectorFilteredCacheKey = '';
    const filteredAtOpen = priorityBuyFilteredCatalog();
    const epicEquipmentVisibleAtOpen = filteredAtOpen.filter(row => row.rarity === 5 && row.equipment).length;
    const visibleByCategoryAtOpen = Object.fromEntries(
        PRIORITY_CATEGORY_ORDER.map(category => [category, filteredAtOpen.filter(row => row.category === category).length])
    );
    ++state.stats.prioritySmartBuySelectorOpens;
    if (autoOpened) ++state.stats.prioritySmartBuySelectorAutoOpens;
    setOperatorMouseInteractive(true, 'Priority Buy item table', true);
    // A55.21: resolve once immediately; ordinary key edges may not be surfaced by the low-level bridge.
    if (!operatorPanicController) {
        operatorPanicControllerResolvedAt = Date.now();
        try { operatorPanicController = contextLibrary.getPlayerController(); } catch (_) { operatorPanicController = undefined; }
    }
    reassertOperatorCursorLease('Priority item table open');
    applyPrioritySelectorNativeUiOnlyLease(true, 'Priority item table open');
    scheduleOperatorCursorReassertions('Priority item table open');
    state.lastAction = `Priority Item Table open • ${catalog.length} source-backed item IDs • ${priorityBuySelectedSet().size} selected`;
    log.info('OMEGAB PRIORITY ITEM TABLE OPENED', {
        source: String(source || 'HUD'),
        autoOpened: Boolean(autoOpened),
        catalogItems: catalog.length,
        visibleMatches: filteredAtOpen.length,
        epicEquipmentVisibleMatches: epicEquipmentVisibleAtOpen,
        visibleByCategory: visibleByCategoryAtOpen,
        filterSemantics: 'RARITY_AND_CATEGORY',
        rarityAuthority: 'ItemAttrCfg.rarityId primary; rarity/qualityId/quality/gradeId/grade fallback',
        selectedCfgIds: Array.from(priorityBuySelectedSet()),
        targetUnits: Object.fromEntries(Array.from(priorityBuySelectedSet()).map(id => [String(id), priorityBuyTargetUnits(id)])),
        rarityFilters: Array.from(prioritySelectorRarityFilters).sort((a,b)=>a-b),
        categoryFilters: Array.from(prioritySelectorCategoryFilters),
        modalInput: Boolean(config.prioritySmartBuyModalInputEnabled),
        typingSources: 'bridge + cached PlayerController held-key edges',
    });
    updateOperatorControlReadout();
    updateHud();
    return true;
}

function closePriorityBuySelector(source = 'HUD PRIORITY ITEM TABLE') {
    if (!prioritySelectorOpen) return true;
    // Release the selector-only native keyboard mode before dropping focus. The
    // ordinary F8 cursor/move/look lease remains owned and is reasserted below.
    applyPrioritySelectorNativeUiOnlyLease(false, `Priority item table close: ${String(source || 'HUD')}`);
    prioritySelectorOpen = false;
    prioritySelectorSearchFocused = false;
    operatorHudControlHoverId = '';
    state.lastAction = `Priority Item Table closed • ${priorityBuySelectedSet().size} selected`;
    log.info('OMEGAB PRIORITY ITEM TABLE CLOSED', {
        source: String(source || 'HUD'),
        selectedCfgIds: Array.from(priorityBuySelectedSet()),
        search: String(prioritySelectorSearch || ''),
    });
    // Keep the ordinary sticky F8 HUD-only lease immediately after selector closure.
    if (operatorMouseInteractive) {
        reassertOperatorCursorLease('Priority item table close -> HUD input lock');
        scheduleOperatorCursorReassertions('Priority close HUD lock');
    }
    updateOperatorControlReadout();
    updateHud();
    return true;
}

function prioritySelectorControlLayout() {
    if (!prioritySelectorOpen) return [];
    const panel = prioritySelectorPanelGeometry();
    const { x, y, w, h } = panel;
    const controls = [];
    const add=(id,type,label,bx,by,bw,bh=24,value=false,extra={})=>{
        const row={id,type,label,x:bx,y:by,w:bw,h:bh,value,...extra};
        row.description=prioritySelectorControlDescription(row);
        controls.push(row);
        return row;
    };
    add('priority_search_focus','input','SEARCH',x+20,y+68,w-150,28,prioritySelectorSearchFocused);
    add('priority_search_clear','button','CLEAR SEARCH',x+w-120,y+68,100,28);

    // A55.24: item type first, then named rarity. No shorthand or numeric-only filters.
    let cy=y+108;
    const catGap=5, catW=Math.floor((w-40-catGap*2)/3);
    const categoryRows=[
        ['items','keys','gems'],
        ['weapons','armor','accessories'],
    ];
    for (const categoryRow of categoryRows) {
        for (let index=0; index<categoryRow.length; ++index) {
            const category=categoryRow[index];
            add(`priority_cat_${category}`,'toggle',priorityCategoryDisplayName(category),x+20+index*(catW+catGap),cy,catW,25,prioritySelectorCategoryFilters.has(category),{categoryKey:category});
        }
        cy+=30;
    }

    const allGap=6, allW=Math.floor((w-40-allGap)/2);
    add('priority_cat_all','button','SHOW ALL ITEM TYPES',x+20,cy,allW,25);
    add('priority_filter_all','button','SHOW ALL RARITIES',x+20+allW+allGap,cy,allW,25);
    cy+=31;

    const rarityGap=5;
    const rarity4W=Math.floor((w-40-rarityGap*3)/4);
    for(let tier=1;tier<=4;++tier)
        add(`priority_filter_${tier}`,'toggle',rarityDisplayName(tier).toUpperCase(),x+20+(rarity4W+rarityGap)*(tier-1),cy,rarity4W,25,prioritySelectorRarityFilters.has(tier),{rarityValue:tier});
    cy+=30;
    const rarity3W=Math.floor((w-40-rarityGap*2)/3);
    for(let tier=5;tier<=7;++tier)
        add(`priority_filter_${tier}`,'toggle',rarityDisplayName(tier).toUpperCase(),x+20+(rarity3W+rarityGap)*(tier-5),cy,rarity3W,25,prioritySelectorRarityFilters.has(tier),{rarityValue:tier});
    cy+=34;

    const rows=priorityBuyFilteredCatalog();
    const pageSize=Math.max(5,positiveInteger(config.prioritySmartBuySelectorRows,11));
    const pageRows=rows.slice(prioritySelectorPage*pageSize, prioritySelectorPage*pageSize+pageSize);
    const selected=priorityBuySelectedSet();
    for(const row of pageRows){
        const target=priorityBuyTargetUnits(row.cfgId);
        const progress=prioritySmartBuyActive && prioritySmartBuyRunSelectedCfgIds.includes(row.cfgId)
            ? ` ${priorityBuyAcquiredUnits(row.cfgId)}/${priorityBuyRunTargetUnits(row.cfgId)}` : '';
        const itemW=w-190;
        add(`priority_result_${row.cfgId}`,'toggle',`${row.name.slice(0,27)} • ${row.categoryName} • ${row.rarityName} • #${row.cfgId} • x${target}${progress}${row.tradable?'':' • NO-AH'}`,x+20,cy,itemW,30,selected.has(row.cfgId),{
            rarityValue:row.rarity, categoryKey:row.category, cfgId:row.cfgId, targetUnits:target,
            tradable:row.tradable, itemResult:true, tooltipTitle:`${row.name.slice(0,32)} • #${row.cfgId}`,
        });
        add(`priority_qty_minus_${row.cfgId}`,'button','−',x+w-154,cy,42,30,false,{compact:true,cfgId:row.cfgId,tooltipTitle:`${row.name.slice(0,26)} target −`});
        add(`priority_qty_plus_${row.cfgId}`,'button','+',x+w-106,cy,42,30,false,{compact:true,cfgId:row.cfgId,tooltipTitle:`${row.name.slice(0,26)} target +`});
        cy+=34;
    }
    const footerY=y+h-48;
    add('priority_page_prev','button','◀ PREV',x+20,footerY,96,27);
    add('priority_page_next','button','NEXT ▶',x+122,footerY,96,27);
    add('priority_clear_selected','button','CLEAR SELECTED',x+230,footerY,130,27);
    add('priority_selector_close','button','CLOSE',x+w-100,footerY,80,27);
    return controls;
}

function hudPaddedControlHit(rows, mouseX, mouseY, padding = undefined) {
    const pad = Math.max(0, Math.min(16, finiteNumber(padding, config.hudHitPaddingPx)));
    const candidates = [];
    for (const row of Array.from(rows || [])) {
        if (!row || row.type === 'section' || row.interactive === false) continue;
        const exact = mouseX>=row.x && mouseX<=row.x+row.w && mouseY>=row.y && mouseY<=row.y+row.h;
        const padded = mouseX>=row.x-pad && mouseX<=row.x+row.w+pad && mouseY>=row.y-pad && mouseY<=row.y+row.h+pad;
        if (!padded) continue;
        const cx=row.x+row.w/2, cy=row.y+row.h/2;
        const distance=(mouseX-cx)*(mouseX-cx)+(mouseY-cy)*(mouseY-cy);
        candidates.push({row,exact,distance});
    }
    candidates.sort((a,b)=>(Number(b.exact)-Number(a.exact)) || (a.distance-b.distance));
    return candidates[0]?.row;
}

function prioritySelectorControlAt(mouseX, mouseY) {
    if (!prioritySelectorOpen) return undefined;
    return hudPaddedControlHit(prioritySelectorControlLayout(), mouseX, mouseY);
}

function drawPrioritySelector(frame) {
    if (!prioritySelectorOpen) return;
    const panel=prioritySelectorPanelGeometry();
    const {x,y,w,h}=panel;
    frame.fillRoundedRect(x,y,w,h,12,'#07000BF5'); frame.roundedRect(x,y,w,h,12,'#C36BF0FF',2);
    frame.fillRoundedRect(x+8,y+8,w-16,58,8,'#1A0725FA'); frame.roundedRect(x+8,y+8,w-16,58,8,'#75358FFF',1);
    frame.text('// PRIORITY SMART BUY • ITEM TABLE',x+18,y+14,'#F4E1FCFF',14);
    const selectedIds=Array.from(priorityBuySelectedSet());
    const selectedUnits=selectedIds.reduce((sum,id)=>sum+priorityBuyTargetUnits(id),0);
    frame.text(`SELECTED ${selectedIds.length} ITEMS / ${selectedUnits} UNITS • FILTER ITEM TYPE + RARITY • F8 HUD INPUT LOCK`,x+18,y+37,'#C7A7D5FF',8);
    const searchBorder=prioritySelectorSearchFocused?'#F0B8FFFF':'#6B3285FF';
    frame.fillRoundedRect(x+20,y+68,w-150,28,5,'#11051AF7'); frame.roundedRect(x+18,y+66,w-146,32,6,searchBorder,prioritySelectorSearchFocused?3:1);
    frame.text(prioritySelectorSearch ? `SEARCH: ${prioritySelectorSearch}` : 'SEARCH: click here, then type item name / cfgId…',x+30,y+76,prioritySelectorSearch?'#F0DEF7FF':'#806E89FF',9);
    const rows=prioritySelectorControlLayout();
    for(const row of rows){
        if(row.type==='input') continue;
        const hovered=operatorMouseInteractive && row.id===operatorHudControlHoverId;
        if(row.type==='toggle'){
            if (row.categoryKey) {
                const visual=hudCategoryVisualIdentity(row.categoryKey,row.value,hovered);
                frame.fillRoundedRect(row.x,row.y,row.w,row.h,5,visual.fill);
                frame.roundedRect(row.x,row.y,row.w,row.h,5,visual.border,row.value?2:1);
                if(row.value){
                    // A55.22 selected category gets an unmistakable OUTER ring, not just an inner tint.
                    frame.roundedRect(row.x-2,row.y-2,row.w+4,row.h+4,7,'#FFF2FFFF',2);
                    frame.fillRoundedRect(row.x+3,row.y+3,4,row.h-6,2,visual.accent);
                    frame.text('ON',row.x+row.w-20,row.y+7,'#FFFFFFFF',7);
                }
                frame.text(row.label,row.x+10,row.y+7,visual.text,8);
            } else if (row.rarityValue && /^priority_filter_/.test(row.id)) {
                const visual=hudRarityVisualIdentity(row.rarityValue,row.value,hovered);
                frame.fillRoundedRect(row.x,row.y,row.w,row.h,5,visual.fill);
                frame.roundedRect(row.x,row.y,row.w,row.h,5,visual.border,row.value?2:1);
                if(row.value) frame.roundedRect(row.x-1,row.y-1,row.w+2,row.h+2,6,'#F7E9FFFF',1);
                frame.text(row.label,row.x+7,row.y+8,visual.text,7);
            } else {
                const visual=row.rarityValue ? hudRarityVisualIdentity(row.rarityValue,row.value,hovered) : undefined;
                frame.fillRoundedRect(row.x,row.y,row.w,row.h,5,visual?.fill || (hovered?'#271037F5':'#13061CF2'));
                frame.roundedRect(row.x,row.y,row.w,row.h,5,row.value?(visual?.border || '#B75AE1FF'):(hovered?'#8E45B5FF':'#432052FF'),row.value?2:1);
                frame.fillRoundedRect(row.x+6,row.y+6,11,11,3,row.value?(visual?.accent || '#A74DD7FF'):'#261130FF');
                frame.text(row.label,row.x+24,row.y+7,row.value?(visual?.text || '#F0DCF8FF'):'#A189ADFF',8);
            }
        } else {
            frame.fillRoundedRect(row.x,row.y,row.w,row.h,5,hovered?'#4B1B63F5':'#21102BF2');
            frame.roundedRect(row.x,row.y,row.w,row.h,5,hovered?'#C56BEEFF':'#5A2A70FF',1);
            frame.text(row.label,row.x+(row.compact?16:8),row.y+7,'#DCC6E6FF',row.compact?10:8);
        }
    }
    const filtered=priorityBuyFilteredCatalog(), pageSize=Math.max(5,positiveInteger(config.prioritySmartBuySelectorRows,11));
    const pages=Math.max(1,Math.ceil(filtered.length/pageSize));
    frame.text(`MATCHES ${filtered.length} • PAGE ${prioritySelectorPage+1}/${pages} • ${prioritySelectorCategoryFilters.size}/6 ITEM TYPES • ${prioritySelectorRarityFilters.size}/7 RARITIES • CHEAPEST VERIFIED FIRST`,x+20,y+h-20,'#A98AB9FF',8);
}

function prioritySelectorControllerEdge(keyName) {
    const name=String(keyName||'');
    if(!name) return false;
    if(!prioritySelectorResolvedKeys[name]) prioritySelectorResolvedKeys[name]=resolveOperatorKeys(name);
    let controller=operatorPanicController;
    const now=Date.now();
    if(!controller && now-operatorPanicControllerResolvedAt>=250){
        operatorPanicControllerResolvedAt=now;
        try{controller=contextLibrary.getPlayerController();}catch(_){controller=undefined;}
        if(controller) operatorPanicController=controller;
    }
    if(!controller) return false;
    let down=false, hasDownSample=false, justPressed=false;
    for(const key of prioritySelectorResolvedKeys[name] || []){
        try {
            if (typeof controller.IsInputKeyDown === 'function') {
                hasDownSample=true;
                if (controller.IsInputKeyDown(key) === true) down=true;
            }
        } catch(_) {}
        try { if(controller.WasInputKeyJustPressed?.(key)===true) justPressed=true; } catch(_) {}
    }
    if (hasDownSample) {
        const edge=down && !prioritySelectorControllerWasDown[name];
        prioritySelectorControllerWasDown[name]=down;
        if (edge) ++state.stats.prioritySmartBuyKeyboardControllerDownEdges;
        // UI-only input can expose a one-frame JustPressed edge while IsInputKeyDown
        // remains false.  A55.21 discarded that valid edge whenever the method existed.
        if (justPressed && !edge) ++state.stats.prioritySmartBuyKeyboardJustPressedFallbackEdges;
        return Boolean(edge || justPressed);
    }
    if (justPressed) ++state.stats.prioritySmartBuyKeyboardJustPressedFallbackEdges;
    return justPressed;
}

function prioritySelectorBridgeEdge(vk, bridge) {
    if(!bridge || typeof bridge.isKeyDown!=='function') return false;
    let down=false; try{down=Boolean(bridge.isKeyDown(vk));}catch(_){}
    const key=String(vk), edge=down&&!prioritySelectorKeyWasDown[key];
    prioritySelectorKeyWasDown[key]=down;
    return edge;
}

function pollPrioritySelectorKeyboard() {
    if (!prioritySelectorOpen || !operatorMouseInteractive || !prioritySelectorSearchFocused) return false;
    let bridge; try{bridge=globalThis.__sharpMistBridge;}catch(_){bridge=undefined;}
    let changed=false;
    const consume=(vk,keyName)=>{
        const bridgeEdge=prioritySelectorBridgeEdge(vk,bridge);
        const controllerEdge=prioritySelectorControllerEdge(keyName);
        if(bridgeEdge) ++state.stats.prioritySmartBuyKeyboardBridgeEdges;
        if(controllerEdge) ++state.stats.prioritySmartBuyKeyboardControllerEdges;
        return Boolean(bridgeEdge||controllerEdge);
    };
    if(consume(0x1B,'Escape')){ closePriorityBuySelector('ESC'); return true; }
    if(consume(0x08,'BackSpace')){ prioritySelectorSearch=prioritySelectorSearch.slice(0,-1); changed=true; }
    if(consume(0x20,'SpaceBar') && prioritySelectorSearch.length<48){ prioritySelectorSearch+=' '; changed=true; }
    for(let vk=0x41;vk<=0x5A;++vk){
        const ch=String.fromCharCode(vk);
        if(consume(vk,ch)&&prioritySelectorSearch.length<48){prioritySelectorSearch+=ch.toLowerCase(); changed=true; ++state.stats.prioritySmartBuyTypedCharacters;}
    }
    const digitNames=['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine'];
    for(let vk=0x30;vk<=0x39;++vk) if(consume(vk,digitNames[vk-0x30])&&prioritySelectorSearch.length<48){prioritySelectorSearch+=String.fromCharCode(vk); changed=true; ++state.stats.prioritySmartBuyTypedCharacters;}
    if(changed){
        prioritySelectorPage=0;
        prioritySelectorFilteredCacheKey='';
        scheduleOperatorMouseAutoRelease();
        reassertOperatorCursorLease('Priority table typing');
        updateOperatorControlReadout();
        updateHud();
    }
    return changed;
}

function activatePrioritySelectorControl(id) {
    const key=String(id||'');
    let m=key.match(/^priority_result_(\d+)$/); if(m) return setPriorityBuyTarget(Number(m[1]),!priorityBuySelectedSet().has(Number(m[1])));
    m=key.match(/^priority_qty_minus_(\d+)$/); if(m){ const id=Number(m[1]); return setPriorityBuyTargetUnits(id,priorityBuyTargetUnits(id)-1,true); }
    m=key.match(/^priority_qty_plus_(\d+)$/); if(m){ const id=Number(m[1]); return setPriorityBuyTargetUnits(id,priorityBuyTargetUnits(id)+1,true); }
    m=key.match(/^priority_filter_([1-7])$/); if(m){ const t=Number(m[1]); if(prioritySelectorRarityFilters.has(t)) prioritySelectorRarityFilters.delete(t); else prioritySelectorRarityFilters.add(t); if(!prioritySelectorRarityFilters.size) prioritySelectorRarityFilters.add(t); ++state.stats.prioritySmartBuyRarityFilterChanges; prioritySelectorPage=0; prioritySelectorFilteredCacheKey=''; state.lastAction=`Smart Buy rarity ${rarityDisplayName(t)} ${prioritySelectorRarityFilters.has(t)?'ON':'OFF'}`; log.info('OMEGAB PRIORITY RARITY FILTER CHANGED',{rarityId:t,rarity:rarityDisplayName(t),enabled:prioritySelectorRarityFilters.has(t),activeRarityIds:Array.from(prioritySelectorRarityFilters).sort((a,b)=>a-b)}); return true; }
    m=key.match(/^priority_cat_(items|keys|gems|weapons|armor|accessories)$/); if(m){ const category=m[1]; if(prioritySelectorCategoryFilters.has(category)) prioritySelectorCategoryFilters.delete(category); else prioritySelectorCategoryFilters.add(category); if(!prioritySelectorCategoryFilters.size) prioritySelectorCategoryFilters.add(category); ++state.stats.prioritySmartBuyCategoryFilterChanges; prioritySelectorPage=0; prioritySelectorFilteredCacheKey=''; state.lastAction=`Smart Buy category ${priorityCategoryDisplayName(category)} ${prioritySelectorCategoryFilters.has(category)?'ON':'OFF'}`; return true; }
    if(key==='priority_cat_all'){ prioritySelectorCategoryFilters=new Set(PRIORITY_CATEGORY_ORDER); ++state.stats.prioritySmartBuyCategoryFilterChanges; prioritySelectorPage=0; prioritySelectorFilteredCacheKey=''; return true; }
    if(key==='priority_filter_all'){ prioritySelectorRarityFilters=new Set([1,2,3,4,5,6,7]); ++state.stats.prioritySmartBuyRarityFilterChanges; prioritySelectorPage=0; prioritySelectorFilteredCacheKey=''; state.lastAction='Smart Buy rarities ALL ON'; log.info('OMEGAB PRIORITY RARITY FILTER CHANGED',{rarityId:'ALL',enabled:true,activeRarityIds:[1,2,3,4,5,6,7]}); return true; }
    if(key==='priority_search_focus'){ prioritySelectorSearchFocused=true; for(const name of Object.keys(prioritySelectorControllerWasDown)) delete prioritySelectorControllerWasDown[name]; for(const keyName of Object.keys(prioritySelectorKeyWasDown)) delete prioritySelectorKeyWasDown[keyName]; reassertOperatorCursorLease('Priority search focus'); applyPrioritySelectorNativeUiOnlyLease(true,'Priority search focus'); return true; }
    if(key==='priority_search_clear'){ prioritySelectorSearch=''; prioritySelectorSearchFocused=true; for(const name of Object.keys(prioritySelectorControllerWasDown)) delete prioritySelectorControllerWasDown[name]; for(const keyName of Object.keys(prioritySelectorKeyWasDown)) delete prioritySelectorKeyWasDown[keyName]; prioritySelectorPage=0; prioritySelectorFilteredCacheKey=''; reassertOperatorCursorLease('Priority search clear'); applyPrioritySelectorNativeUiOnlyLease(true,'Priority search clear'); return true; }
    if(key==='priority_clear_selected'){ state.operatorSettings.priorityBuySelectedCfgIds=[]; prioritySelectorFilteredCacheKey=''; persistOperatorSettings(); return true; }
    if(key==='priority_page_prev'){ prioritySelectorPage=Math.max(0,prioritySelectorPage-1); return true; }
    if(key==='priority_page_next'){ const n=priorityBuyFilteredCatalog().length, ps=Math.max(5,positiveInteger(config.prioritySmartBuySelectorRows,11)); prioritySelectorPage=Math.min(Math.max(0,Math.ceil(n/ps)-1),prioritySelectorPage+1); return true; }
    if(key==='priority_selector_close') return closePriorityBuySelector('CLOSE button');
    return false;
}

function requestPrioritySmartBuy(source='HUD PRIORITY SMART BUY') {
    if (!config.prioritySmartBuyEnabled || shutdownRequested || disposed) return false;
    if (!prioritySmartBuyActive && (operatorStructuralOperationActive() || operatorWarehouseTierSellQueued || operatorWarehouseTierSellInProgress)) { hudControlToast('omegaberg.com: finish/cancel current Sell Held/Delist/Warehouse action before Priority Smart Buy'); return false; }
    if (prioritySmartBuyActive) {
        prioritySmartBuyActive=false; prioritySmartBuyPaused=false; ++state.stats.prioritySmartBuyStops;
        // Preserve the run snapshot until any already-dispatched Priority BUY settles;
        // otherwise a late/partial delivery could lose its per-item progress accounting.
        state.lastAction='Priority Smart Buy stopped; already-dispatched BUY may still settle';
        log.info('OMEGAB PRIORITY SMART BUY STOPPED',{source,satisfied:Array.from(prioritySmartBuySatisfiedCfgIds),progress:prioritySmartBuyRunSelectedCfgIds.map(id=>({cfgId:id,acquired:priorityBuyAcquiredUnits(id),target:priorityBuyRunTargetUnits(id)}))});
        return true;
    }
    if (state.pendingBuy?.prioritySmartBuy) {
        state.lastAction='Priority Smart Buy restart waiting for the previously dispatched Priority BUY to settle';
        hudControlToast('Priority Smart Buy: wait for the previous dispatched buy to settle');
        return false;
    }
    const selected=Array.from(priorityBuySelectedSet()).filter(id=>validTradableConfig(id));
    if(!selected.length){
        state.lastAction='Priority Smart Buy needs a target; opening Priority Item Table';
        hudControlToast('omegaberg.com: choose target item(s) in the Priority Item Table');
        openPriorityBuySelector(`${source} • AUTO OPEN`, true);
        return true;
    }
    prioritySmartBuyRunSelectedCfgIds=selected.slice();
    prioritySmartBuyRunTargetUnitsByCfgId=Object.create(null);
    prioritySmartBuyAcquiredUnitsByCfgId=Object.create(null);
    for(const id of selected){ prioritySmartBuyRunTargetUnitsByCfgId[String(id)]=priorityBuyTargetUnits(id); prioritySmartBuyAcquiredUnitsByCfgId[String(id)]=0; }
    prioritySmartBuySatisfiedCfgIds.clear(); prioritySmartBuyCursor=0; prioritySmartBuyLastProbeAt=0;
    for(const k of Object.keys(prioritySmartBuyNextProbeAtByCfgId)) delete prioritySmartBuyNextProbeAtByCfgId[k];
    prioritySmartBuyActive=true; prioritySmartBuyPaused=!operatorDesiredLive; ++state.stats.prioritySmartBuyRuns;
    cancelSuperAggressiveReadAhead('Priority Smart Buy requested');
    const targetTotal=selected.reduce((sum,id)=>sum+priorityBuyRunTargetUnits(id),0);
    state.lastAction=`Priority Smart Buy ${prioritySmartBuyPaused?'armed/paused':'active'} • ${selected.length} item(s) / ${targetTotal} units`;
    log.info('OMEGAB PRIORITY SMART BUY STARTED',{source,targets:selected.map(id=>({cfgId:id,item:itemName(id),targetUnits:priorityBuyRunTargetUnits(id)})),perItemTargets:true,cheapestExactLevelFirst:true,paused:prioritySmartBuyPaused});
    if(!tickInProgress && state.running) void tick(true);
    return true;
}

function prioritySmartBuyDispatchAllowed() {
    return Boolean(prioritySmartBuyActive && !prioritySmartBuyPaused && operatorDesiredLive && state.liveArmed && !operatorDesiredReadOnlyAllMarket() &&
        !operatorDelistAllQueued&&!operatorDelistAllInProgress&&!operatorSellAllQueued&&!operatorSellAllInProgress&&!operatorWarehouseTierSellQueued&&!operatorWarehouseTierSellInProgress&&!shutdownRequested&&!disposed);
}

function prioritySmartBuyRecommendedTickDelayMs(){ return prioritySmartBuyActive ? (prioritySmartBuyPaused?500:Math.max(100,finiteNumber(config.prioritySmartBuyProbeIntervalMs,400))) : Math.max(5,finiteNumber(config.scanIntervalMs,5)); }

function transferPatternItemInfo(cfgId) {
    const cfg = itemConfig(cfgId);
    const name = itemName(cfgId);
    const normalizedName = name.toLowerCase();
    const qualityValue = itemQualityValue(cfgId);
    const blueValues = Array.isArray(config.transferPatternBlueQualityValues)
        ? config.transferPatternBlueQualityValues.map(value => finiteNumber(value, NaN))
            .filter(Number.isFinite)
        : [];
    return {
        cfgId: finiteNumber(cfgId),
        name,
        keyLike: /(^|\s|[-_])key(s)?($|\s|[-_])/i.test(normalizedName) ||
            normalizedName.includes(' key'),
        equipment: isEquipmentConfig(cfg),
        qualityValue,
        blueQualified: !blueValues.length || blueValues.includes(qualityValue),
    };
}

function purchaseUnitLimit(budget = budgetSnapshot()) {
    const base = positiveInteger(config.maximumUnitsPerPurchase, 5);
    if (!config.highRiskHighRewardMode) return base;
    const high = Math.max(base, positiveInteger(config.highRiskMaximumUnitsPerPurchase, base));
    if (finiteNumber(budget?.gold) < 10000) return base;
    if (finiteNumber(budget?.gold) < 15000) return Math.min(high, Math.max(base, 6));
    return high;
}

function sellAtFairValueRatioForPolicy(policy) {
    let ratio = finiteNumber(config.sellAtFairValueRatio, 0.92);
    if (!config.highRiskHighRewardMode) return Math.max(0.50, Math.min(0.995, ratio));
    const performance = policy?.performance;
    if (performance?.provenFastSeller) {
        ratio = Math.max(ratio, finiteNumber(config.highRiskFastSellerFairValueRatio, 0.96));
    } else if (finiteNumber(performance?.completedSales) > 0) {
        ratio = Math.max(ratio, finiteNumber(config.highRiskKnownSellerFairValueRatio, 0.94));
    }
    return Math.max(0.50, Math.min(0.995, ratio));
}


function tradeStackUnitsForCfg(cfgId) {
    const cfg = itemConfig(cfgId);
    const source = Math.floor(finiteNumber(cfg?.tradeHeapMax));
    // Mistfall source authority: LobbyTradeSellPromptView uses
    // `this.itemCfg['tradeHeapMax'] ?? 1` for the legal listing-quantity limit.
    // If the field is absent/unreadable/non-positive, fail closed to one unit; never
    // revive the old x5 material estimate because that can under-reserve stall slots.
    return source > 0 ? source : 1;
}

function tradeListingSlotsForQuantity(cfgId, quantity) {
    return Math.max(1, Math.ceil(
        Math.max(1, positiveInteger(quantity, 1)) / Math.max(1, tradeStackUnitsForCfg(cfgId))
    ));
}

function parseAuctionRuleDateMs(value) {
    const text = String(value || '').trim();
    const match = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})-(\d{1,2}):(\d{2})$/);
    if (!match) return NaN;
    const [, y, m, d, hh, mm] = match.map(Number);
    const date = new Date(y, Math.max(0, m - 1), d, hh, mm, 0, 0);
    const ms = date.getTime();
    return Number.isFinite(ms) ? ms : NaN;
}

function auctionRuleIndex() {
    if (auctionRuleIndexCache) return auctionRuleIndexCache;
    const byCfgId = new Map();
    if (!config.auctionRuleSourceIntelligenceEnabled || !AuctionRuleCfg) {
        auctionRuleIndexCache = { byCfgId, rows: 0, cfgIds: 0, available: false };
        return auctionRuleIndexCache;
    }
    let rows = [];
    try {
        const dynamicMap = CfgMgr.getDynamicMap(AuctionRuleCfg);
        rows = dynamicMap && typeof dynamicMap.values === 'function'
            ? Array.from(dynamicMap.values()) : Object.values(dynamicMap || {});
    } catch (_) { rows = []; }
    for (const rule of rows) {
        const cfgId = Math.floor(finiteNumber(rule?.itemId));
        const price = Math.floor(finiteNumber(rule?.price));
        if (!(cfgId > 0) || !(price > 0)) continue;
        if (!byCfgId.has(cfgId)) byCfgId.set(cfgId, []);
        byCfgId.get(cfgId).push({
            id: Math.floor(finiteNumber(rule?.id)),
            price,
            startAt: parseAuctionRuleDateMs(rule?.startTime),
            endAt: parseAuctionRuleDateMs(rule?.endTime),
            // Deliberately retain only opaque source metadata. `type` semantics are unknown.
            sourceType: Math.floor(finiteNumber(rule?.type)),
        });
    }
    for (const list of byCfgId.values()) list.sort((a,b)=>a.price-b.price||a.id-b.id);
    auctionRuleIndexCache = { byCfgId, rows: rows.length, cfgIds: byCfgId.size, available: byCfgId.size > 0 };
    ++state.stats.auctionRuleIndexBuilds;
    state.stats.auctionRuleRowsIndexed = Math.max(finiteNumber(state.stats.auctionRuleRowsIndexed), rows.length);
    state.stats.auctionRuleCfgIdsIndexed = Math.max(finiteNumber(state.stats.auctionRuleCfgIdsIndexed), byCfgId.size);
    return auctionRuleIndexCache;
}

function activeAuctionRulesForCfg(cfgId, now = Date.now()) {
    const index = auctionRuleIndex();
    const rows = Array.from(index.byCfgId.get(Math.floor(finiteNumber(cfgId))) || []);
    return rows.filter(row =>
        (!Number.isFinite(row.startAt) || now >= row.startAt) &&
        (!Number.isFinite(row.endAt) || now <= row.endAt)
    );
}

function auctionRulePriceLevels(cfgId, now = Date.now()) {
    return Array.from(new Set(activeAuctionRulesForCfg(cfgId, now).map(row=>row.price).filter(v=>v>0)))
        .sort((a,b)=>a-b);
}

function auctionRuleWallMatch(cfgId, liveWallPrice, now = Date.now()) {
    const wall = Math.floor(finiteNumber(liveWallPrice));
    if (!(wall > 0)) return undefined;
    const tolerance = Math.max(0, Math.floor(finiteNumber(config.auctionRuleWallMatchToleranceGold, 1)));
    let best;
    for (const price of auctionRulePriceLevels(cfgId, now)) {
        const distance = Math.abs(wall - price);
        if (distance > tolerance) continue;
        if (!best || distance < best.distance || (distance === best.distance && price < best.price))
            best = { price, distance };
    }
    return best;
}

function sourceGraduatedRecordActive(record, now = Date.now()) {
    return Boolean(record && finiteNumber(record.sourceGraduatedUntil) > now);
}

function sourceGraduationIdentityEligible(cfgId, categoryLabel) {
    if (!config.auctionRuleSourceGraduationEnabled || String(categoryLabel || '') !== 'Items / Urban') return false;
    if (bulkWallCfgManuallyQuarantined(cfgId)) return false;
    if (!validTradableConfig(cfgId) || permanentlyBindsOnAcquire(cfgId)) return false;
    const quality = finiteNumber(itemQualityValue(cfgId), NaN);
    const allowed = Array.from(config.auctionRuleSourceGraduationQualities || []).map(v=>finiteNumber(v,NaN));
    return allowed.includes(quality) && auctionRulePriceLevels(cfgId).length > 0;
}

function sourceGraduationProbeEligible(listing, categoryLabel, now = Date.now()) {
    if (!listing?.key || !sourceGraduationIdentityEligible(listing.cfgId, categoryLabel)) return false;
    const ask = Math.max(1, Math.floor(finiteNumber(listing.price)));
    const minimumProfit = Math.max(1, Math.floor(finiteNumber(config.auctionRuleSourceProbeMinimumPotentialProfit, 1)));
    for (const anchor of auctionRulePriceLevels(listing.cfgId, now)) {
        const conservativeExit = clampToItemLimits(listing.cfgId, Math.max(1, anchor - 1));
        if (conservativeExit <= ask) continue;
        const result = projectedBulkWallResult(ask, conservativeExit, 1);
        if (finiteNumber(result.totalProfit) >= minimumProfit) return true;
    }
    return false;
}

function bulkWallCandidateProbeAuthorized(listing, categoryLabel, now = Date.now()) {
    if (bulkWallCfgVerifiedForCategory(listing?.cfgId, categoryLabel)) return true;
    const allowed = sourceGraduationProbeEligible(listing, categoryLabel, now);
    if (allowed) ++state.stats.auctionRuleSourceProbeCandidates;
    return allowed;
}

function warehouseLiquidityWitness(cfgId) {
    return state.warehouseLiquidityByCfgId?.[String(Math.floor(finiteNumber(cfgId)))] || undefined;
}

function noteWarehouseLiquidityWitness(record, quantity, saleMinutes, completedAt = Date.now()) {
    if (!config.warehouseLiquidityWitnessEnabled || !warehouseTierManagedRecord(record)) return undefined;
    const cfgId = Math.floor(finiteNumber(record.cfgId));
    if (!(cfgId > 0)) return undefined;
    const key = String(cfgId);
    const prior = warehouseLiquidityWitness(cfgId) || { cfgId, sales:0, units:0, ewmaSaleMinutes:0, lastSaleAt:0, lastSaleUnitPrice:0 };
    const alpha = Math.max(0.05, Math.min(0.95, finiteNumber(config.warehouseLiquidityWitnessEwmaAlpha, 0.30)));
    const minutes = Math.max(0.01, finiteNumber(saleMinutes, 0.01));
    prior.sales = Math.max(0, Math.floor(finiteNumber(prior.sales))) + 1;
    prior.units = Math.max(0, Math.floor(finiteNumber(prior.units))) + Math.max(1, positiveInteger(quantity, 1));
    prior.ewmaSaleMinutes = finiteNumber(prior.ewmaSaleMinutes) > 0
        ? finiteNumber(prior.ewmaSaleMinutes) * (1 - alpha) + minutes * alpha : minutes;
    prior.lastSaleAt = completedAt;
    prior.lastSaleUnitPrice = Math.max(0, Math.floor(finiteNumber(record.saleUnitPrice)));
    state.warehouseLiquidityByCfgId[key] = prior;
    ++state.stats.warehouseLiquidityWitnessSales;
    state.stats.warehouseLiquidityWitnessUnits += Math.max(1, positiveInteger(quantity, 1));
    return prior;
}

function auctionRuleSeedCategoryForCfg(cfgId) {
    const text = String(Math.floor(finiteNumber(cfgId)));
    if (text.startsWith('903')) return categories.find(row=>row.label==='Items / Urban');
    if (text.startsWith('904')) return categories.find(row=>row.label==='Items / Forging');
    return undefined;
}

function auctionRuleSeedPotential(cfgId, ask, now = Date.now()) {
    const unitAsk = Math.max(1, Math.floor(finiteNumber(ask)));
    const minimumProfit = Math.max(1, Math.floor(finiteNumber(config.auctionRuleBatchSeedMinimumPotentialProfit, 1)));
    let best;
    for (const anchor of auctionRulePriceLevels(cfgId, now)) {
        const sale = clampToItemLimits(cfgId, Math.max(1, anchor - 1));
        if (sale <= unitAsk) continue;
        const projected = projectedBulkWallResult(unitAsk, sale, 1);
        if (finiteNumber(projected.totalProfit) < minimumProfit) continue;
        if (!best || projected.totalProfit > best.totalProfit)
            best = { anchor, sale, totalProfit: projected.totalProfit, roi: projected.roi };
    }
    return best;
}

function auctionRuleSeedCfgIds() {
    if (auctionRuleSeedCfgIdsCache) return auctionRuleSeedCfgIdsCache;
    const rows = [];
    for (const [cfgId] of auctionRuleIndex().byCfgId) {
        const text = String(Math.floor(finiteNumber(cfgId)));
        if (!text.startsWith('903')) continue; // source-graduation expansion is Urban-only
        const quality = finiteNumber(itemQualityValue(cfgId), NaN);
        if (![4, 5].includes(quality)) continue;
        if (!validTradableConfig(cfgId) || permanentlyBindsOnAcquire(cfgId)) continue;
        rows.push(Math.floor(finiteNumber(cfgId)));
    }
    rows.sort((a,b)=>a-b);
    auctionRuleSeedCfgIdsCache = rows;
    return auctionRuleSeedCfgIdsCache;
}

function auctionRuleBatchSeedCandidates(now = Date.now()) {
    if (!config.auctionRuleBatchSeedEnabled || !itemRapidWatchBatchSupported()) return [];
    const maximumCandidates = Math.max(8, positiveInteger(config.auctionRuleBatchSeedMaximumCandidates, 96));
    const activePolicy = activeRarityQualityPolicy(now);
    const activeQualities = new Set([
        ...Array.from(activePolicy?.primaryQualities || []),
        ...Array.from(activePolicy?.secondaryQualities || []),
    ].map(v=>finiteNumber(v,NaN)));
    const pool = [];
    for (const cfgId of auctionRuleSeedCfgIds()) {
        const category = auctionRuleSeedCategoryForCfg(cfgId);
        if (!category || !lockedWallFarmCategoryAllowed(category)) continue;
        if (!sourceGraduationIdentityEligible(cfgId, category.label)) continue;
        if (bulkWallCfgVerifiedForCategory(cfgId, category.label)) continue;
        const quality = finiteNumber(itemQualityValue(cfgId), NaN);
        if (!activeQualities.has(quality) || !lockedWallFarmQualityAllowed(cfgId)) continue;
        if (!auctionRulePriceLevels(cfgId, now).length) continue;
        const key = signature(cfgId, []);
        const existing = bulkWallRecord(key, false);
        if (existing && !existing.sourceSeedOnly) continue;
        const witness = warehouseLiquidityWitness(cfgId);
        const fastMinutes = finiteNumber(witness?.ewmaSaleMinutes, NaN);
        const witnessBonus = Number.isFinite(fastMinutes)
            ? Math.max(0, Math.min(
                finiteNumber(config.warehouseLiquidityWitnessSeedMaximumBonus, 180000),
                180000 / Math.max(1, fastMinutes),
            )) : 0;
        pool.push({ cfgId, key, category, quality, existing, witnessBonus,
            lastPolledAt: finiteNumber(existing?.batchLastPolledAt) });
    }
    if (!pool.length) return [];
    pool.sort((a,b)=> finiteNumber(b.witnessBonus)-finiteNumber(a.witnessBonus) ||
        finiteNumber(a.lastPolledAt)-finiteNumber(b.lastPolledAt) || a.cfgId-b.cfgId);
    const boundedPool = pool.slice(0, maximumCandidates);
    const slots = Math.max(0, Math.min(2, positiveInteger(config.auctionRuleBatchSeedSlots, 2)));
    const start = auctionRuleSeedCursor % boundedPool.length;
    const selectedRaw=[];
    for (let i=0;i<boundedPool.length && selectedRaw.length<slots;i++)
        selectedRaw.push(boundedPool[(start+i)%boundedPool.length]);
    auctionRuleSeedCursor = (start + Math.max(1, selectedRaw.length)) % boundedPool.length;
    const selected = selectedRaw.map(raw => {
        const record = raw.existing || bulkWallRecord(raw.key, true);
        record.cfgId = raw.cfgId;
        record.item = itemName(raw.cfgId);
        record.qualityValue = raw.quality;
        record.categoryKey = raw.category.key;
        record.categoryLabel = raw.category.label;
        record.sourceSeedOnly = true;
        return { record, sourceSeed:true, score: 10000 + raw.witnessBonus };
    });
    state.stats.auctionRuleBatchSeedSelections += selected.length;
    return selected;
}

function maybeWakeAuctionRuleSeedFromBatch(row, now = Date.now()) {
    const record = row?.record;
    if (!record?.sourceSeedOnly) return false;
    const potential = auctionRuleSeedPotential(record.cfgId, row.price, now);
    if (!potential) return false;
    record.lastAggregatePrice = Math.max(1, Math.floor(finiteNumber(row.price)));
    record.sourceSeedWakeUntil = now + Math.max(500, finiteNumber(config.auctionRuleBatchSeedWakeTtlMs, 2500));
    record.sourceSeedPotentialProfit = finiteNumber(potential.totalProfit);
    record.updatedAt = now;
    ++state.stats.auctionRuleBatchSeedWakeups;
    return true;
}

function recordCategoryServerCoverage(category, routeLane, response, returnedRows, now = Date.now()) {
    const total = Math.max(0, Math.floor(finiteNumber(response?.total)));
    const returned = Math.max(0, Math.floor(finiteNumber(returnedRows)));
    const key = `${String(category?.key || 'unknown')}|${String(routeLane || 'DEFAULT')}`;
    const prior = state.categoryCoverageByKey[key] || { observations:0, maxTotal:0, maxReturned:0, truncations:0 };
    prior.categoryKey = category?.key;
    prior.categoryLabel = category?.label;
    prior.routeLane = String(routeLane || 'DEFAULT');
    prior.observations += 1;
    prior.lastTotal = total;
    prior.lastReturned = returned;
    prior.maxTotal = Math.max(finiteNumber(prior.maxTotal), total);
    prior.maxReturned = Math.max(finiteNumber(prior.maxReturned), returned);
    prior.lastTruncated = total > returned;
    if (total > returned) prior.truncations += 1;
    prior.updatedAt = now;
    state.categoryCoverageByKey[key] = prior;
    ++state.stats.categoryServerCoverageObservations;
    state.stats.categoryServerReportedRows += total;
    state.stats.categoryServerReturnedRows += returned;
    if (total > returned) ++state.stats.categoryServerTruncationObservations;
    state.stats.categoryServerMaximumTotal = Math.max(finiteNumber(state.stats.categoryServerMaximumTotal), total);
    categoryServerMaximumTotalThisRun = Math.max(categoryServerMaximumTotalThisRun, total);
    return prior;
}

function bulkWallRecord(key, create = false) {
    if (!key) return undefined;
    let record = state.bulkWallObservationsBySignature[key];
    if (!record && create) {
        record = {
            signature: key,
            cfgId: finiteNumber(String(key).split('|', 1)[0]),
            observations: 0,
            qualifyingObservations: 0,
            consecutiveQualifying: 0,
            wallPriceChanges: 0,
            lastWallPrice: 0,
            lastWallUnits: 0,
            wallUnitDecreaseEvents: 0,
            wallUnitDecreaseUnits: 0,
            wallUnitIncreaseEvents: 0,
            wallUnitIncreaseUnits: 0,
            lastUnitsBelowWall: 0,
            qualityValue: undefined,
            lastExitCompetitionUnits: 0,
            lastProbeAt: 0,
            lastQualifyingAt: 0,
            lastOpportunityAt: 0,
            lastProjectedRoi: 0,
            lastProjectedProfit: 0,
            lastProjectedQuantity: 0,
            lastProjectedBuyUnitPrice: 0,
            lastProjectedSaleUnitPrice: 0,
            profitPriorityFirstSeenAt: 0,
            profitPriorityLastProfit: 0,
            profitPriorityDeferrals: 0,
            ewmaCompetitionRatio: 0,
            ewmaOpportunity: 0,
            completedSales: 0,
            completedUnits: 0,
            returnedListings: 0,
            saleMinutesEwma: 0,
            profitEwma: 0,
            lastSaleAt: 0,
            lastReturnAt: 0,
            updatedAt: Date.now(),
        };
        state.bulkWallObservationsBySignature[key] = record;
    }
    return record;
}

function pruneBulkWallRecords(now = Date.now()) {
    const maximumAge = Math.max(
        10 * 60 * 1000,
        finiteNumber(config.bulkWallAdaptiveRecordMaximumAgeMs, 6 * 60 * 60 * 1000),
    );
    const records = state.bulkWallObservationsBySignature || {};
    for (const [key, record] of Object.entries(records)) {
        if (!record) {
            delete records[key];
            continue;
        }
        const latest = Math.max(
            finiteNumber(record.updatedAt),
            finiteNumber(record.lastProbeAt),
            finiteNumber(record.lastSaleAt),
            finiteNumber(record.lastReturnAt),
        );
        if (latest > 0 && now - latest > maximumAge)
            delete records[key];
    }
    const maximum = positiveInteger(config.bulkWallAdaptiveMaximumRecords, 500);
    const keys = Object.keys(records);
    if (keys.length <= maximum) return;
    keys.sort((left, right) =>
        Math.max(
            finiteNumber(records[left]?.updatedAt),
            finiteNumber(records[left]?.lastSaleAt),
        ) - Math.max(
            finiteNumber(records[right]?.updatedAt),
            finiteNumber(records[right]?.lastSaleAt),
        )
    );
    for (const key of keys.slice(0, keys.length - maximum))
        delete records[key];
}

function bulkWallAdaptiveSnapshot(key, now = Date.now()) {
    const record = bulkWallRecord(key, false);
    if (!record) return undefined;
    const decayMs = Math.max(
        60 * 1000,
        finiteNumber(config.bulkWallAdaptiveDecayMs, 30 * 60 * 1000),
    );
    const age = Math.max(0, now - finiteNumber(record.updatedAt, now));
    const freshness = Math.max(0.05, Math.exp(-age / decayMs));
    const required = Math.max(1, positiveInteger(config.bulkWallRequirePersistenceScans, 3));
    const persistence = Math.min(
        1,
        Math.max(0, finiteNumber(record.consecutiveQualifying) / required),
    );
    const observations = Math.max(1, finiteNumber(record.observations, 1));
    const wallChangePenalty = Math.min(
        0.70,
        finiteNumber(record.wallPriceChanges) / observations,
    );
    const wallStability = Math.max(0, persistence * (1 - wallChangePenalty));
    const competitionScore = Math.max(
        0,
        Math.min(1, 1 - finiteNumber(record.ewmaCompetitionRatio)),
    );
    const opportunityFrequency = Math.max(
        0,
        Math.min(1, finiteNumber(record.ewmaOpportunity)),
    );
    const fastSaleMinutes = Math.max(
        0.5,
        finiteNumber(config.bulkWallAdaptiveFastSaleMinutes, 5),
    );
    const saleMinutes = finiteNumber(record.saleMinutesEwma);
    const saleSpeedScore = saleMinutes > 0
        ? Math.max(0, Math.min(1, 1 - saleMinutes / (fastSaleMinutes * 3)))
        : 0.50;
    const completedSales = Math.max(0, Math.floor(finiteNumber(record.completedSales)));
    const returnedListings = Math.max(0, Math.floor(finiteNumber(record.returnedListings)));
    const outcomeScore = completedSales + returnedListings > 0
        ? completedSales / Math.max(1, completedSales + returnedListings * 2)
        : 0.50;
    const baseScore = (
        wallStability * 0.30 +
        competitionScore * 0.25 +
        saleSpeedScore * 0.20 +
        outcomeScore * 0.15 +
        opportunityFrequency * 0.10
    );
    // v4.4: a stable wall with no profitable stock below it is market structure,
    // not a trading opportunity. Once we have enough observations, suppress its
    // adaptive priority until actual economic opportunities start appearing.
    const economicUsefulness = finiteNumber(record.qualifyingObservations) >= 3
        ? Math.max(0.35, Math.min(1, 0.35 + opportunityFrequency * 0.65))
        : 1;
    const score = freshness * baseScore * economicUsefulness;
    const estimatedGoldPerHour = saleMinutes > 0 && finiteNumber(record.profitEwma) > 0
        ? finiteNumber(record.profitEwma) * 60 / saleMinutes
        : 0;
    return {
        score: Math.max(0, Math.min(1, score)),
        freshness,
        wallStability,
        competitionScore,
        saleSpeedScore,
        outcomeScore,
        opportunityFrequency,
        completedSales,
        completedUnits: Math.max(0, Math.floor(finiteNumber(record.completedUnits))),
        returnedListings,
        averageSaleMinutes: saleMinutes > 0 ? saleMinutes : undefined,
        estimatedGoldPerHour,
        consecutiveQualifying: Math.max(
            0,
            Math.floor(finiteNumber(record.consecutiveQualifying)),
        ),
        lastWallPrice: finiteNumber(record.lastWallPrice),
        lastWallUnits: finiteNumber(record.lastWallUnits),
        lastProbeAt: finiteNumber(record.lastProbeAt),
        lastOpportunityAt: finiteNumber(record.lastOpportunityAt),
    };
}

function bulkWallAdaptiveLeaders(now = Date.now(), maximum = 5) {
    pruneBulkWallRecords(now);
    const rows = [];
    for (const key of Object.keys(state.bulkWallObservationsBySignature || {})) {
        const snapshot = bulkWallAdaptiveSnapshot(key, now);
        if (!snapshot) continue;
        rows.push({ key, ...snapshot });
    }
    rows.sort((left, right) =>
        right.score - left.score ||
        right.estimatedGoldPerHour - left.estimatedGoldPerHour ||
        right.consecutiveQualifying - left.consecutiveQualifying ||
        finiteNumber(right.lastOpportunityAt) - finiteNumber(left.lastOpportunityAt)
    );
    return rows.slice(0, Math.max(1, positiveInteger(maximum, 5))).map(row => ({
        item: itemName(finiteNumber(String(row.key).split('|', 1)[0])),
        signature: row.key,
        score: Number(row.score.toFixed(3)),
        wallStability: Number(row.wallStability.toFixed(3)),
        competitionScore: Number(row.competitionScore.toFixed(3)),
        saleSpeedScore: Number(row.saleSpeedScore.toFixed(3)),
        opportunityFrequency: Number(row.opportunityFrequency.toFixed(3)),
        completedSales: row.completedSales,
        returnedListings: row.returnedListings,
        averageSaleMinutes: Number.isFinite(row.averageSaleMinutes)
            ? Number(row.averageSaleMinutes.toFixed(1)) : undefined,
        estimatedGoldPerHour: row.estimatedGoldPerHour > 0
            ? Math.floor(row.estimatedGoldPerHour) : 0,
        consecutiveQualifying: row.consecutiveQualifying,
        lastWallPrice: row.lastWallPrice,
        lastWallUnits: row.lastWallUnits,
    }));
}


function perfNowMs() {
    try {
        const value = globalThis.performance?.now?.();
        if (Number.isFinite(value)) return value;
    } catch (_) {}
    return Date.now();
}

function observeLocalPerf(name, startedAt) {
    const elapsed = Math.max(0, perfNowMs() - finiteNumber(startedAt));
    const record = localPerf[name] || (localPerf[name] = { samples: 0, emaMs: 0, maxMs: 0, lastMs: 0 });
    record.lastMs = elapsed;
    record.maxMs = Math.max(finiteNumber(record.maxMs), elapsed);
    record.emaMs = record.samples > 0
        ? finiteNumber(record.emaMs) * 0.85 + elapsed * 0.15
        : elapsed;
    ++record.samples;
    return elapsed;
}

function localPerformanceSnapshot() {
    const output = {};
    for (const [name, record] of Object.entries(localPerf)) {
        output[name] = {
            samples: finiteNumber(record.samples),
            emaMs: Number(finiteNumber(record.emaMs).toFixed(3)),
            maxMs: Number(finiteNumber(record.maxMs).toFixed(3)),
        };
    }
    return output;
}

function sessionStat(name) {
    return Math.max(0, finiteNumber(state.stats?.[name]) - finiteNumber(statsAtStart?.[name]));
}

function runElapsedHours(now = Date.now()) {
    return runtimeStartedAt > 0 ? Math.max(1 / 3600, (now - runtimeStartedAt) / 3600000) : 1 / 3600;
}

function exactGold(value) {
    return String(Math.round(finiteNumber(value))).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function resilienceShadowSnapshot(now = Date.now(), recordCheck = false) {
    if (!config.resilienceShadowEnabled || !resilienceLease || !resilience)
        return { available: false };
    try {
        const status = resilienceLease.status?.();
        if (!status) return { available: false };
        if (recordCheck) ++state.stats.resilienceShadowChecks;
        const campStage = status.stage === resilience.stages?.CAMP;
        const authenticated = status.phase === resilience.phases?.READY && status.authenticated === true;
        const ours = Boolean(lobbyNetworkConnected() && reconnectCampReady());
        const theirs = Boolean(campStage && authenticated);
        const disagreement = ours !== theirs;
        const key = `${ours ? 1 : 0}:${theirs ? 1 : 0}:${status.stageName || status.stage || ''}:${status.phase || ''}`;
        if (disagreement && key !== lastResilienceShadowKey) {
            ++state.stats.resilienceShadowDisagreements;
            lastResilienceShadowKey = key;
        } else if (!disagreement) {
            lastResilienceShadowKey = '';
        }
        if (
            disagreement &&
            recordCheck &&
            now - lastResilienceShadowWarnAt >= Math.max(10000, finiteNumber(config.resilienceShadowWarnCooldownMs, 60000))
        ) {
            lastResilienceShadowWarnAt = now;
            log.warn('A15 RESILIENCE SHADOW DISAGREEMENT (READ-ONLY)', {
                sniperReady: ours,
                resilienceReady: theirs,
                stage: status.stageName || status.stage,
                phase: status.phase,
                authenticated: status.authenticated,
                note: 'Shadow telemetry only; A12 reconnect remains authoritative.',
            });
        }
        return {
            available: true,
            ready: theirs,
            sniperReady: ours,
            disagreement,
            stage: status.stageName || String(status.stage ?? ''),
            phase: String(status.phase ?? ''),
            authenticated: Boolean(status.authenticated),
        };
    } catch (_) {
        return { available: false };
    }
}

function requestAuthoritativeInventoryAudit(reason, includeStash = false) {
    if (!config.authoritativeInventoryAuditEnabled) return false;
    const next = {
        reason: String(reason || 'uncertain inventory state'),
        includeStash: Boolean(includeStash),
        requestedAt: Date.now(),
    };
    if (authoritativeInventoryAuditRequest) {
        authoritativeInventoryAuditRequest.includeStash =
            Boolean(authoritativeInventoryAuditRequest.includeStash || next.includeStash);
        authoritativeInventoryAuditRequest.reason =
            `${authoritativeInventoryAuditRequest.reason}; ${next.reason}`.slice(0, 180);
        return false;
    }
    authoritativeInventoryAuditRequest = next;
    ++state.stats.authoritativeInventoryAuditTriggers;
    return true;
}

async function maybeRunAuthoritativeInventoryAudit() {
    const request = authoritativeInventoryAuditRequest;
    if (!request || !config.authoritativeInventoryAuditEnabled || !lobbyNetworkConnected())
        return false;
    const now = Date.now();
    const cooldown = Math.max(1000, finiteNumber(config.authoritativeInventoryAuditCooldownMs, 4000));
    if (now - lastAuthoritativeInventoryAuditAt < cooldown) return false;
    if (!stashCtrl || typeof stashCtrl.requestInventoryInfo !== 'function') {
        authoritativeInventoryAuditRequest = undefined;
        ++state.stats.authoritativeInventoryAuditFailures;
        return false;
    }
    authoritativeInventoryAuditRequest = undefined;
    lastAuthoritativeInventoryAuditAt = now;
    const beforeDeliveries = finiteNumber(state.stats.purchaseDeliveries);
    const startedAt = perfNowMs();
    try {
        await pacedRequest(
            'A18 authoritative inventory audit',
            () => stashCtrl.requestInventoryInfo(true),
            Math.max(2000, finiteNumber(config.authoritativeInventoryAuditTimeoutMs, 5000)),
            () => state.running && !disposed && lobbyNetworkConnected(),
        );
        ++state.stats.authoritativeInventoryAudits;
        if (
            request.includeStash &&
            typeof stashCtrl.requestStashInfo === 'function'
        ) {
            await pacedRequest(
                'A18 authoritative stash audit',
                () => stashCtrl.requestStashInfo(),
                Math.max(2000, finiteNumber(config.authoritativeInventoryAuditTimeoutMs, 5000)),
                () => state.running && !disposed && lobbyNetworkConnected(),
            );
            ++state.stats.authoritativeInventoryAuditStashRefreshes;
        }
        settleLateDeliveryWatches(Date.now(), true);
        settlePendingBuy();
        recoverReturnedManagedListings(false);
        const recovered = Math.max(0, finiteNumber(state.stats.purchaseDeliveries) - beforeDeliveries);
        state.stats.authoritativeInventoryAuditRecoveredDeliveries += recovered;
        if (recovered > 0) {
            log.success('A18 AUTHORITATIVE INVENTORY AUDIT RECOVERED DELIVERY', {
                reason: request.reason,
                recoveredDeliveries: recovered,
                includeStash: request.includeStash,
            });
        }
        return true;
    } catch (error) {
        ++state.stats.authoritativeInventoryAuditFailures;
        log.warn('A18 authoritative inventory audit failed; normal reconciliation continues', {
            reason: request.reason,
            error: String(error?.message || error).slice(0, 160),
        });
        return false;
    } finally {
        observeLocalPerf('inventoryAudit', startedAt);
    }
}

function stopHudPaint() {
    if (!hudPaintHandle) return;
    try {
        if (typeof hudPaintHandle.remove === 'function') hudPaintHandle.remove();
        else if (typeof hudPaintHandle.dispose === 'function') hudPaintHandle.dispose();
        else if (typeof hudPaintHandle === 'function') hudPaintHandle();
    } catch (_) {
    } finally {
        hudPaintHandle = undefined;
    }
}

function dungeonMicroHudMetrics(now = Date.now()) {
    const used = (() => {
        try { return Math.max(0, listLength(tradeModel?.myStallGoods)); }
        catch (_) { return 0; }
    })();
    const maximum = (() => {
        try { return Math.max(0, Math.floor(finiteNumber(tradeModel?.getStallNum?.()))); }
        catch (_) { return 0; }
    })();
    const free = Math.max(0, maximum - used);
    const committed = Math.max(0, finiteNumber(sessionStat('buyGoldCommitted')));
    const verifiedNet = finiteNumber(sessionStat('projectedCompletedProfitLearned'));
    const deferredRevenue = DUNGEON_COEXIST_PROFILE
        ? Math.max(0, finiteNumber(tradeModel?.revenue?.v))
        : 0;
    const roi = committed > 0 ? verifiedNet / committed : 0;
    const profitAbs = Math.abs(verifiedNet);
    const profitCompact = profitAbs >= 10000
        ? `${(profitAbs / 1000).toFixed(1)}k`
        : `${Math.round(profitAbs)}g`;
    const deferredCompact = deferredRevenue >= 10000
        ? `${(deferredRevenue / 1000).toFixed(1)}k`
        : `${Math.round(deferredRevenue)}g`;
    const activityLabel = dungeonBackgroundContextUnproven ? 'AH WARMUP' : 'AH ACTIVE';
    return {
        at: now, used, maximum, free, roi, verifiedNet, deferredRevenue,
        text: `${activityLabel} • STALL ${used}/${maximum || '?'} • P ${verifiedNet >= 0 ? '+' : '-'}${profitCompact} • PEND ${deferredCompact}`,
    };
}

function refreshDungeonMicroHudSnapshot(now = Date.now(), force = false) {
    if (!auctionDungeonActive(now)) return false;
    const interval = Math.max(500, finiteNumber(config.dungeonMicroHudRefreshMs, 1000));
    if (!force && dungeonMicroHudSnapshot && now - dungeonMicroHudSnapshotAt < interval) return false;
    dungeonMicroHudSnapshotAt = now;
    const perfStartedAt = perfNowMs();
    dungeonMicroHudSnapshot = dungeonMicroHudMetrics(now);
    observeLocalPerf('microHudSnapshot', perfStartedAt);
    ++state.stats.dungeonMicroHudSnapshotRefreshes;
    return true;
}

function stopDungeonMicroHud() {
    if (dungeonMicroHudPaintHandle) {
        try {
            if (typeof dungeonMicroHudPaintHandle.remove === 'function') dungeonMicroHudPaintHandle.remove();
            else if (typeof dungeonMicroHudPaintHandle.dispose === 'function') dungeonMicroHudPaintHandle.dispose();
            else if (typeof dungeonMicroHudPaintHandle === 'function') dungeonMicroHudPaintHandle();
        } catch (_) {}
        dungeonMicroHudPaintHandle = undefined;
        ++state.stats.dungeonMicroHudStops;
    }
    dungeonMicroHudSnapshot = undefined;
    dungeonMicroHudSnapshotAt = 0;
}

function startDungeonMicroHud() {
    if (!config.dungeonMicroHudEnabled || !auctionDungeonActive() || dungeonMicroHudPaintHandle)
        return Boolean(dungeonMicroHudPaintHandle);
    if (!drawing || typeof drawing.onDraw !== 'function') return false;
    refreshDungeonMicroHudSnapshot(Date.now(), true);
    const priority = Math.max(1000, Math.min(
        10000000,
        Math.floor(finiteNumber(config.dungeonMicroHudDrawingPriority, 1000000)),
    ));
    try {
        dungeonMicroHudPaintHandle = drawing.onDraw(frame => {
            const snap = dungeonMicroHudSnapshot;
            if (!snap || !dungeonBackgroundActive) return;
            const x = Math.max(2, Math.floor(finiteNumber(config.dungeonMicroHudX, 6)));
            const y = Math.max(2, Math.floor(finiteNumber(config.dungeonMicroHudY, 6)));
            const w = Math.max(220, Math.floor(finiteNumber(config.dungeonMicroHudWidth, 250)));
            const h = Math.max(22, Math.floor(finiteNumber(config.dungeonMicroHudHeight, 26)));
            frame.fillRoundedRect(x, y, w, h, 5, '#08020EC2');
            frame.roundedRect(x, y, w, h, 5, '#5D2477C8', 1);
            frame.text(String(snap.text || ''),
                x + 7, y + 7, '#EEDDF6FF', 9);
        }, { priority, name: 'auction-sniper-dungeon-company-microhud' });
        ++state.stats.dungeonMicroHudStarts;
        return true;
    } catch (_) {
        dungeonMicroHudPaintHandle = undefined;
        return false;
    }
}

function syncDungeonMicroHud(now = Date.now()) {
    if (!config.dungeonMicroHudEnabled || !auctionDungeonActive(now)) {
        dungeonMicroHudCombatPeerSuppressed = false;
        if (dungeonMicroHudPaintHandle) stopDungeonMicroHud();
        return false;
    }
    const combatPeer = combatPeerCoexistenceSnapshot(now);
    if (config.dungeonCombatPeerSuppressMicroHud && combatPeer.active) {
        if (!dungeonMicroHudCombatPeerSuppressed) {
            dungeonMicroHudCombatPeerSuppressed = true;
            ++state.stats.dungeonCombatPeerMicroHudSuppressions;
        }
        if (dungeonMicroHudPaintHandle) stopDungeonMicroHud();
        return false;
    }
    dungeonMicroHudCombatPeerSuppressed = false;
    refreshDungeonMicroHudSnapshot(now, false);
    if (!dungeonMicroHudPaintHandle) startDungeonMicroHud();
    return Boolean(dungeonMicroHudPaintHandle);
}


