function prioritySelectorControlDescription(row) {
    const id = String(row?.id || '');
    if (id === 'priority_search_focus')
        return 'Filter the Smart Buy table by item name or cfgId. Search is combined with enabled item-type and rarity filters; searching never arms a purchase.';
    if (id === 'priority_search_clear')
        return 'Clear only the Smart Buy table search text. Item-type/rarity filters and selected exact item targets stay unchanged.';
    if (id === 'priority_cat_all')
        return 'Enable all six Smart Buy item-type visibility filters. This affects the table only; rows must still be selected before SMART BUY can purchase them.';
    if (id === 'priority_filter_all')
        return 'Enable all T1-T7 Smart Buy rarity visibility filters. This affects the table only and does not change Sell Warehouse filters.';
    const categoryMatch = id.match(/^priority_cat_(items|keys|gems|weapons|armor|accessories)$/);
    if (categoryMatch)
        return `Smart Buy table filter: include ${priorityCategoryDisplayName(categoryMatch[1])}. Item type is ANDed with enabled rarities. Visibility alone never buys; select an exact row then start SMART BUY.`;
    const rarityMatch = id.match(/^priority_filter_([1-7])$/);
    if (rarityMatch) {
        const tier = Number(rarityMatch[1]);
        return `Smart Buy table filter: include ${rarityDisplayName(tier)} (T${tier}). Rarity is ANDed with enabled item types and uses the same source-backed resolver as Sell Warehouse.`;
    }
    const resultMatch = id.match(/^priority_result_(\d+)$/);
    if (resultMatch)
        return `Select exact cfgId #${resultMatch[1]} for Smart Buy. The shown x target is the maximum units this run; live cheapest exact-book price and safety are rechecked before every BUY.`;
    if (/^priority_qty_minus_\d+$/.test(id))
        return 'Reduce this exact Smart Buy item target by 1 unit. The row is selected automatically and never goes below x1.';
    if (/^priority_qty_plus_\d+$/.test(id))
        return 'Increase this exact Smart Buy item target by 1 unit. The row is selected automatically; normal bankroll/capacity/exact-book safety still applies.';
    if (id === 'priority_page_prev' || id === 'priority_page_next')
        return 'Move through currently filtered Smart Buy catalog pages. Paging changes visibility only; selected exact item targets are preserved.';
    if (id === 'priority_clear_selected')
        return 'Clear all exact Smart Buy item selections. Search and visibility filters stay as they are.';
    if (id === 'priority_selector_close')
        return 'Close the Smart Buy item table. Selected exact targets remain saved; closing the table does not start or stop Smart Buy.';
    return '';
}

