    if (operatorMouseInteractive) {
        if (typeof wbl.SetInputMode_GameAndUIEx === 'function') {
            try { wbl.SetInputMode_GameAndUIEx(controller, undefined, lockMode, false, false); return true; } catch (_) {}
            try { wbl.SetInputMode_GameAndUIEx(controller, undefined, lockMode, false); return true; } catch (_) {}
        }
        if (typeof wbl.SetInputMode_GameAndUI === 'function') {
            try { wbl.SetInputMode_GameAndUI(controller, undefined, true, false); return true; } catch (_) {}
            try { wbl.SetInputMode_GameAndUI(controller, undefined, true); return true; } catch (_) {}
            try { wbl.SetInputMode_GameAndUI(controller, undefined); return true; } catch (_) {}
        }
    }
