function reconnectUiRoleMainViewReady(view) {
    if (!view) return { ready: false, reason: 'NO_ROLE_VIEW' };
    if (reactiveBoolean(safeProperty(view, 'nextStepChoosed')))
        return { ready: false, reason: 'ROLE_SELECTION_ALREADY_IN_PROGRESS' };
    if (reactiveBoolean(safeProperty(view, 'animPlaying')))
        return { ready: false, reason: 'ROLE_VIEW_INTRO_ANIMATION' };
    const widget = safeProperty(view, 'widget');
    const listView = safeProperty(widget, 'ListView_Roles');
    const getSelected = safeProperty(listView, 'GetSelectedIndex');
    let selectedIndex = -1;
    if (typeof getSelected === 'function') {
        try { selectedIndex = Math.floor(finiteNumber(getSelected.call(listView), -1)); }
        catch (_) { selectedIndex = -1; }
    }
    if (selectedIndex < 0)
        return { ready: false, reason: 'ROLE_NOT_SELECTED', selectedIndex };
    return { ready: true, selectedIndex };
}

function maybeAutoConfirmReconnectRoleSelection(recovery, now = Date.now()) {
    if (!config.automaticReconnectUiRoleSelectConfirmEnabled)
        return { attempted: false, success: false, reason: 'DISABLED' };
    if (recovery.uiRoleSelectCompletedAt)
        return { attempted: false, success: true, reason: 'ALREADY_COMPLETED' };
    const enterSeenAt = Math.max(
        finiteNumber(recovery.uiEnterGameSeenAt),
        finiteNumber(recovery.uiLastEnterGameAt),
    );
    if (!enterSeenAt)
        return { attempted: false, success: false, reason: 'ROLE_STAGE_NOT_REQUESTED' };
    const settleMs = Math.max(500,
        finiteNumber(config.automaticReconnectUiRoleSelectSettleMs, 1200));
    if (now - enterSeenAt < settleMs)
        return { attempted: false, success: false, reason: 'ROLE_STAGE_SETTLING' };

    const maximum = Math.max(1,
        positiveInteger(config.automaticReconnectUiRoleSelectMaximumAttempts, 3));
    const attempts = Math.max(0,
        Math.floor(finiteNumber(recovery.uiRoleSelectConfirmAttempts)));
    if (attempts >= maximum)
        return { attempted: false, success: false, reason: 'ROLE_SELECT_ATTEMPTS_EXHAUSTED' };
    const retryMs = Math.max(3000,
        finiteNumber(config.automaticReconnectUiRoleSelectRetryMs, 15000));
    if (recovery.uiLastRoleSelectConfirmAt &&
        now - finiteNumber(recovery.uiLastRoleSelectConfirmAt) < retryMs)
        return { attempted: false, success: false, reason: 'ROLE_SELECT_RETRY_BACKOFF' };

    const view = reconnectUiDirectRoleMainView(recovery);
    if (!view) return { attempted: false, success: false, reason: 'ROLE_VIEW_NOT_READY' };
    const readiness = reconnectUiRoleMainViewReady(view);
    if (!readiness.ready)
        return { attempted: false, success: false, reason: readiness.reason, readiness };

    const confirm = safeProperty(view, 'onClickEnterGame');
    if (typeof confirm !== 'function' || Math.max(0, finiteNumber(confirm.length)) !== 0)
        return { attempted: false, success: false, reason: 'ROLE_CONFIRM_METHOD_UNAVAILABLE' };

    recovery.uiRoleSelectConfirmAttempts = attempts + 1;
    recovery.uiLastRoleSelectConfirmAt = now;
    recovery.uiRoleSelectSubmittedAt = now;
    recovery.updatedAt = now;
    ++state.stats.automaticReconnectUiRoleSelectAttempts;
    let success = false;
    let error;
    try {
        confirm.call(view);
        success = true;
    } catch (caught) {
        error = errorText(caught);
    }
    log.warn('AUCTION RECONNECT AUTO ROLE SELECT CONFIRM', {
        attempt: recovery.uiRoleSelectConfirmAttempts,
        generation: networkGeneration,
        method: 'RoleMainView.onClickEnterGame',
        selectedIndex: readiness.selectedIndex,
        success,
        error,
        nextAction: 'Wait for LoginCtrl.onEnterGame and source-backed camp-ready/HUD proof before reopening Auction House.',
    });
    return { attempted: true, success, error, readiness };
}

