function reconnectUiExplicitLoginFailureMessageBox(recovery, now = Date.now()) {
    if (!config.automaticReconnectUiLoginFailureEnabled) return { present: false };
    const model = reconnectMessageModelFromController();
    if (!model) return { present: false };
    let data;
    const getData = safeProperty(model, 'getCurDisplayMessageBoxData');
    if (typeof getData === 'function') {
        try { data = getData.call(model); } catch (_) {}
    }
    const handle = safeProperty(model, 'messageBoxWindow');
    const getView = safeProperty(handle, 'getView');
    let view;
    if (typeof getView === 'function') {
        try { view = getView.call(handle); } catch (_) {}
    }
    if (!data && view) {
        const getCur = safeProperty(view, 'getCurMessage');
        if (typeof getCur === 'function') {
            try { data = getCur.call(view); } catch (_) {}
        }
    }
    const promptId = Math.floor(finiteNumber(safeProperty(data, 'promptId'), -999999));
    const title = String(safeProperty(data, 'title') || '');
    const expectedId = Math.floor(finiteNumber(config.automaticReconnectUiLoginFailurePromptId, -1));
    const expectedTitle = String(config.automaticReconnectUiLoginFailureTitle || 'Login Failed');
    if (promptId !== expectedId || title !== expectedTitle)
        return { present: false, promptId, title };

    // Only auto-acknowledge the dynamic -1 box when it follows a real UI-generated
    // requestLogin. This prevents unrelated promptId -1 dialogs from being clicked.
    const requestAt = finiteNumber(recovery?.uiLoginRequestSeenAt);
    if (!requestAt || now - requestAt < 0 || now - requestAt > 60000)
        return { present: true, ready: false, promptId, title,
            reason: 'LOGIN_FAILURE_NOT_ASSOCIATED_WITH_RECENT_UI_LOGIN' };
    if (!view) return { present: true, ready: false, promptId, title,
        reason: 'LOGIN_FAILURE_VIEW_NOT_READY' };
    return { present: true, ready: true, promptId, title, view, model };
}

