    marketMutationMinimumGapObservedMs = Number.POSITIVE_INFINITY;
    marketMutationPeakRollingWindow = 0;
    marketMutationExplicitGuardUntil = 0;
    marketMutationExplicitGuardGapMs = 0;
    requestDispatchReservationTail = Promise.resolve();
    marketMutationReservationTail = Promise.resolve();
    requestDispatchReservationsActive = 0;
    marketMutationReservationsActive = 0;
    strongBuyMutationRunwayUntil = 0;
    strongBuyMutationRunwaySignature = '';
    strongBuyMutationRunwayProfit = 0;
    strongBuyMutationRunwayRoi = 0;
    superAggressiveReadAheadQueue = [];
    clearSuperAggressiveReadAheadExtraLaunchTimer();
    superAggressiveReadAheadFallbackUntil = 0;
    state.running = true;
    runtimeStartedAt = Date.now();
    runtimeGoldAtStart = undefined;
    lastObservedGold = undefined;
    hudHourlyBuckets = [];
    hudHourlyCurrentIndex = -1;
